const EMO_RE = new RegExp("(?:" + Object.keys(EMO).sort((x, y) => y.length - x.length).join("|") + ")[\uFE0E\uFE0F]?[\u{1F3FB}-\u{1F3FF}]?", "gu");
const emoOn = () => true;   // во всём приложении
function deEmoji(root){
  if(!root || !emoOn()) return;
  const nodes = [];
  if(root.nodeType===3) nodes.push(root);
  else if(root.nodeType===1){ const w = document.createTreeWalker(root, NodeFilter.SHOW_TEXT); let n; while((n = w.nextNode())) nodes.push(n); }
  nodes.forEach(n => {
    const p = n.parentNode, v = n.nodeValue; if(!p || !v) return;
    EMO_RE.lastIndex = 0; if(!EMO_RE.test(v)) return;
    if(p.closest && p.closest("textarea,input,option,select,svg,script,style,title")) return;
    EMO_RE.lastIndex = 0; const f = document.createDocumentFragment(); let i = 0, m;
    while((m = EMO_RE.exec(v))){ if(m.index > i) f.appendChild(document.createTextNode(v.slice(i, m.index)));
      const t = document.createElement("template"); t.innerHTML = picSvg(EMO[m[0].replace(/[\uFE0E\uFE0F\u{1F3FB}-\u{1F3FF}]/gu, "")] || "smile", "ei"); f.appendChild(t.content); i = m.index + m[0].length; }
    if(i < v.length) f.appendChild(document.createTextNode(v.slice(i)));
    p.replaceChild(f, n);
  });
}
(function emoWatch(){
  const mo = new MutationObserver(ms => { if(!emoOn()) return; ms.forEach(m => { if(m.type==="characterData") deEmoji(m.target); else m.addedNodes.forEach(deEmoji); }); });
  const start = () => { deEmoji(document.body); mo.observe(document.body, {childList:true, subtree:true, characterData:true}); };
  if(document.readyState==="loading") document.addEventListener("DOMContentLoaded", start); else start();
})();

