// ---------------- закрытый доступ: данные на сайте зашифрованы (scripts/seal.py), ключ получается из кода доступа
// формат файла: "RSP1" + iv(12) + AES-GCM. Незашифрованные файлы (локальная разработка) читаются как есть.
const SITE_SALT="raspisanie-site-v1", OFFER_V=3;
let SKEY=null;
const codeNorm2 = c => (c||"").trim().toLowerCase();
async function keyBytes(code){ const base=await crypto.subtle.importKey("raw", new TextEncoder().encode(codeNorm2(code)), "PBKDF2", false, ["deriveBits"]);
  return new Uint8Array(await crypto.subtle.deriveBits({name:"PBKDF2", salt:new TextEncoder().encode(SITE_SALT), iterations:200000, hash:"SHA-256"}, base, 256)); }
async function calTokenOf(code){ const h=new Uint8Array(await crypto.subtle.digest("SHA-256", new TextEncoder().encode("cal|"+codeNorm2(code)))); return [...h].map(b=>b.toString(16).padStart(2,"0")).join("").slice(0,24); }
async function siteKey(){ if(SKEY) return SKEY; const raw=localStorage.getItem("siteKey"); if(!raw) return null;
  SKEY=await crypto.subtle.importKey("raw", Uint8Array.from(atob(raw), c=>c.charCodeAt(0)), "AES-GCM", false, ["decrypt"]); return SKEY; }
const isSealed = u => u.length>16 && u[0]===82 && u[1]===83 && u[2]===80 && u[3]===49;
async function openBytes(u, key){ return new Uint8Array(await crypto.subtle.decrypt({name:"AES-GCM", iv:u.slice(4,16)}, key, u.slice(16))); }
async function sfetch(url, soft){
  const r=await fetch(url); if(!r.ok) return {ok:false, status:r.status, json:async()=>null};
  let u=new Uint8Array(await r.arrayBuffer());
  if(isSealed(u)){ const k=await siteKey(); if(!k) throw new Error("nokey");
    try{ u=await openBytes(u, k); }catch(e){ if(!soft) keyRejected(); throw e; } }
  return {ok:true, status:200, bytes:u, json:async()=>JSON.parse(new TextDecoder().decode(u))};
}
// код поменяли — старый ключ не подходит: забываем его и показываем вход заново (один раз за сеанс)
async function keyRejected(){
  if(sessionStorage.getItem("keyReset")) return;
  try{ const r=await fetch("check.bin?v="+Date.now()); if(!r.ok) return; const u=new Uint8Array(await r.arrayBuffer()); if(!isSealed(u)) return;
    try{ await openBytes(u, await siteKey()); return; }catch(e){} }   // ключ подходит — значит, это старая копия файла, ничего не трогаем
  catch(e){ return; }   // нет сети — проверить нельзя, ключ не трогаем
  sessionStorage.setItem("keyReset","1"); localStorage.removeItem("siteKey"); location.reload(); }
// ссылка «контакты преподавателей от старосты»: #tc=<файл>.<ключ>. Ключ запоминаем и сразу убираем из адресной строки
{ const m=location.hash.match(/[#&]tc=([0-9a-f]{16})\.([A-Za-z0-9_-]{43})/);
  if(m){ const cur=LS.get("tcShare",null); if(!cur || cur.f!==m[1]){ localStorage.setItem("tcShare", JSON.stringify({f:m[1], k:m[2], ok:false})); localStorage.setItem("tcsDirty","1"); } sessionStorage.setItem("tcsNew","1");
    const rest=location.hash.slice(1).split("&").filter(x=>!x.startsWith("tc=")).join("&");
    history.replaceState(history.state, "", location.pathname+location.search+(rest?"#"+rest:"")); } }
// ссылка на главу одногруппника («Мои главы», mych.js): #mych=<id> — запоминаем до входа, откроется в Словаре
{ const m=location.hash.match(/[#&]mych=([A-Za-z0-9_-]{6,24})/);
  if(m){ sessionStorage.setItem("mychIn", m[1]);
    const rest=location.hash.slice(1).split("&").filter(x=>!x.startsWith("mych=")).join("&");
    history.replaceState(history.state, "", location.pathname+location.search+(rest?"#"+rest:"")); } }
// экран входа: код доступа (если сайт закрыт) и правила пользования
async function gate(){
  const hk=(location.hash.match(/[#&]k=([^&]+)/)||[])[1]; let hashCode=""; try{ hashCode=hk?decodeURIComponent(hk).trim():""; }catch(e){ hashCode=""; }
  if(hashCode) history.replaceState(history.state, "", location.pathname+location.search);   // код из ссылки не оставляем в адресной строке
  let closed=true, chk=null, hashOk=false;
  try{ const r=await fetch("check.bin?v="+Date.now()); if(r.ok){ chk=new Uint8Array(await r.arrayBuffer()); closed=isSealed(chk); } else closed=false; }
  catch(e){   // офлайн: проверить код нельзя. Ключ есть — пускаем; нет ключа, но есть код — получаем ключ из кода; существующий ключ не перезаписываем
    const c0=hashCode||localStorage.getItem("siteCode")||"";
    if(!localStorage.getItem("siteKey") && c0){ try{ const raw=await keyBytes(c0); localStorage.setItem("siteKey", btoa(String.fromCharCode(...raw))); localStorage.setItem("calTok", await calTokenOf(c0)); localStorage.setItem("siteCode", c0); }catch(e2){} }
    closed=false; }
  // код из ссылки: если подходит — применяем молча, без экрана входа (экран только при неверном коде или новых правилах)
  if(hashCode && chk && closed){ try{ const raw=await keyBytes(hashCode), key=await crypto.subtle.importKey("raw", raw, "AES-GCM", false, ["decrypt"]); await openBytes(chk, key);
      localStorage.setItem("siteKey", btoa(String.fromCharCode(...raw))); localStorage.setItem("calTok", await calTokenOf(hashCode)); localStorage.setItem("siteCode", hashCode); SKEY=key; sessionStorage.removeItem("keyReset"); hashOk=true; }catch(e){} }
  const haveKey=!!localStorage.getItem("siteKey");
  if(haveKey && chk && closed && !hashOk){ try{ await openBytes(chk, await siteKey()); }catch(e){ localStorage.removeItem("siteKey"); SKEY=null; } }
  const needCode = closed && !localStorage.getItem("siteKey");
  const needOffer = +localStorage.getItem("offerOk")!==OFFER_V;
  if(!needCode && !needOffer) return;
  await new Promise(done=>{
    const g=document.createElement("div"); g.id="gate"; document.body.appendChild(g);
    const draw=()=>{ const t=L(), err=g.dataset.err||"";
      g.innerHTML=`<div class="gbox"><div class="glang"><button data-l="ru" class="${state.lang==="ru"?"on":""}">RU</button><button data-l="zh" class="${state.lang==="zh"?"on":""}">中文</button></div>
        <img src="icon.svg" alt="" class="glogo"><h1>${t.gateT}</h1><p class="muted">${t.gateSub}</p>
        ${needCode?`<label class="gcode">${t.gateCode}<input id="g_code" autocomplete="off" autocapitalize="off" spellcheck="false" value="${esc(g.dataset.code||hashCode)}" placeholder="${t.gateCodePh}"></label>${err?`<p class="gerr">${err}</p>`:""}`:""}
        <div class="goffer"><b>${t.offerT}</b>${t.offerBody}</div>
        <button class="btn wide" id="g_ok">${t.offerOk}</button></div>`;
      g.querySelectorAll(".glang button").forEach(b=>b.onclick=()=>{ g.dataset.code=($("g_code")||{}).value||""; state.lang=b.dataset.l; LS.set("lang",state.lang); draw(); });
      $("g_ok").onclick=async()=>{
        const btn=$("g_ok"); if(btn.disabled) return; btn.disabled=true;
        try{
          if(needCode){ const code=($("g_code").value||"").trim(); if(!code) throw new Error(L().gateNeed);
            btn.textContent="…"; const raw=await keyBytes(code), key=await crypto.subtle.importKey("raw", raw, "AES-GCM", false, ["decrypt"]);
            if(chk){ try{ await openBytes(chk, key); }catch(e){ throw new Error(L().gateBad); } }
            localStorage.setItem("siteKey", btoa(String.fromCharCode(...raw))); localStorage.setItem("calTok", await calTokenOf(code)); localStorage.setItem("siteCode", code); SKEY=key; sessionStorage.removeItem("keyReset"); }
          localStorage.setItem("offerOk", String(OFFER_V)); g.remove(); done();
        }catch(e){ g.dataset.err=e.message||L().gateBad; g.dataset.code=($("g_code")||{}).value||""; draw(); }
      };
      const inp=$("g_code"); if(inp){ inp.onkeydown=e=>{ if(e.key==="Enter") $("g_ok").click(); }; }
    };
    draw();
  });
}
