// красный/оранжевый в интерфейсе спорят с пометками «экзамен» и «внимание»
const warmWarning = hex => { const [h,s]=hexToHsl(hex); return s>35 && (h<=40 || h>=345); };
// контраст по WCAG: насколько цвет отличается от фона (1…21)
const lum = h => { const c=hexRgb(h).map(v=>{ v/=255; return v<=.03928?v/12.92:Math.pow((v+.055)/1.055,2.4); }); return .2126*c[0]+.7152*c[1]+.0722*c[2]; };
const contrast = (a,b) => { const x=lum(a), y=lum(b); return (Math.max(x,y)+.05)/(Math.min(x,y)+.05); };
// подогнать цвет, чтобы он не сливался с фоном (минимум 3:1 — как требуют правила доступности для кнопок и выделения)
function readable(hex, bg, min=3){
  let [h,s,l]=hexToHsl(hex), c=hex;
  const dark = lum(bg) < .2;
  for(let i=0;i<60 && contrast(c,bg)<min;i++){ l += dark?1.5:-1.5; l=Math.max(5,Math.min(95,l)); c=hslToHex(h,s,l); }
  return c;
}
