function orthEaster(y){ const a=y%4, b=y%7, c=y%19, d=(19*c+15)%30, e=(2*a+4*b-d+34)%7, m=Math.floor((d+e+114)/31), day=(d+e+114)%31+1; return Date.UTC(y,m-1,day+13); }
// Масленица: понедельник масленичной недели (за 55 дней до православной Пасхи), неделя — пн…вс
const MASL_DATES=HOL_YEARS.map(y=>new Date(orthEaster(y)-55*864e5).toISOString().slice(0,10));
