// ==/HOLIDAYS==
// какой праздник в этот день (без учёта настроек)
function holMatch(date){
  const md=date.slice(5);
  return HOLI.find(h=> h.r ? h.r.some(([a,b])=> a<=b ? md>=a&&md<=b : md>=a||md<=b)
    : h.cny.some(x=>{ const d=daysBetween(x,date); return d>=(h.from!=null?h.from:-7) && d<=(h.to!=null?h.to:15); })) || null;
}
function inMD(...rs) { const md=spbNow().today.slice(5); return rs.some(([a,b])=>md>=a&&md<=b); }
function nearDate(list, d, from, to){ d=d||spbNow().today; return list.some(x=>{ const n=Math.round((Date.parse(d)-Date.parse(x))/864e5); return n>=from && n<=to; }); }
function otherBigDay(t){ const h=holMatch(spbNow().today); return h && h.w===1 && h.t!==t; }
// сам китайский Новый год (канун, день, следующий день) важнее маленьких праздников; в остальные дни окна — уступает им
// празднуем 4 дня: пятница, выходные и «киберпонедельник» (до 30 ноября — с 1 декабря уже Новый год)
const bfWeek = d => { d=d||spbNow().today; const n=daysBetween(bfDate(+d.slice(0,4)), d); return n>=0 && n<=3 && d.slice(5)<="11-30"; };
const bfDay = () => decorOn() && bfWeek();
function maslWeek(){ return nearDate(MASL_DATES, null, 0, 6); }
function maslDecor(){ return decorOn() && maslWeek() && !otherBigDay("h_masl") && !cnyCore(); }
const maslIdx = () => { const m=MASL_DATES.find(x=>{ const n=daysBetween(x,spbNow().today); return n>=0&&n<=6; }); return m?daysBetween(m,spbNow().today):-1; };
function cnyCore(){ return nearDate(CNY_DATES, null, -1, 1); }
function cnyDecor(){ return decorOn() && nearDate(CNY_DATES, null, -10, 2) && !nySeason() && (cnyCore() || (!otherBigDay("h_cny") && !maslWeek() && !inMD(["01-24","01-26"],["02-12","02-14"],["02-22","02-23"]))); }
function moonDecor(){ return decorOn() && nearDate(MOON_DATES, null, -5, 3) && !otherBigDay("h_moon"); }
function hallSeason(){ const md=spbNow().today.slice(5); return md>="10-06" && md<="11-02"; }   // после Дня учителя (5 октября)
function hallDecor(){ return decorOn() && hallSeason() && !moonDecor(); }   // в День учителя тема Хэллоуина остаётся (без мигания), рамка — учительская
function foolDay(){ return spbNow().today.slice(5)==="04-01"; }
function foolDecor(){ return decorOn() && foolDay(); }
function foolHat(){ const md=spbNow().today.slice(5); return decorOn() && (md==="04-01" || md==="04-02"); }
// раздел «Праздники» в настройках виден, только когда какой-то праздник идёт
// маленькие праздники: окна дней (картинки — docs/art, CC0 с Wikimedia Commons)
const studDay = () => decorOn() && !cnyCore() && inMD(["01-24","01-26"],["11-16","11-18"]);
const valDay = () => decorOn() && !cnyCore() && inMD(["02-12","02-14"]);
const mar8Day = () => decorOn() && inMD(["03-06","03-08"]);
const feb23Day = () => decorOn() && !cnyCore() && inMD(["02-22","02-23"]);
const sep1Day = () => decorOn() && inMD(["09-01","09-02"]);
const teachDay = () => decorOn() && inMD(["09-10","09-10"],["10-05","10-05"]);
function holidayNow(){ return nySeason() || maslWeek() || bfWeek() || nearDate(CNY_DATES,null,-10,2) || nearDate(MOON_DATES,null,-5,3) || hallSeason() || !!holMatch(spbNow().today); }
function applyTheme(){
  const t = LS.get("theme","auto");
  const dark = t==="dark" || (t==="auto" && matchMedia("(prefers-color-scheme: dark)").matches);
  document.documentElement.dataset.theme = dark ? "dark" : "light";
  const bg = dark ? "#1c1a27" : "#ffffff";
  const hc=document.documentElement.classList; hc.toggle("ny", nyDecor()); hc.toggle("cny", cnyDecor()); hc.toggle("hall", hallDecor()); hc.toggle("fool", foolDecor()); hc.toggle("masl", maslDecor()); hc.toggle("bf", bfDay()); hc.toggle("noanim", !animOn()); hc.toggle("eternal", false);
  const own = LS.get("accent","violet")!=="violet";
  let wt=false; try{ wt=winterThemeOn(); }catch(e){}   // при самом первом вызове награды ещё не объявлены
  hc.toggle("winter", wt);
  const a = readable(own ? accentBase() : wt ? "#1e7fd0" : nyDecor() ? "#17855a" : cnyDecor() ? "#c62828" : hallDecor() ? "#e8710a" : foolDecor() ? "#e0367a" : maslDecor() ? "#d97706" : bfDay() ? "#a67c00" : (decorOn()&&spbNow().today.slice(5)==="05-09") ? "#b71c1c" : accentBase(), bg, 3);
  // значок во вкладке браузера на праздник (иконку установленного приложения сайт менять не может)
  { const fav = nyDecor()?"🎄":cnyDecor()?"🧧":hallDecor()?"🎃":foolDecor()?"🤡":maslDecor()?"🥞":bfDay()?"🏷️":"", l=document.querySelector('link[rel="icon"]');
    if(l) l.href = fav ? `data:image/svg+xml,${encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><text y=".9em" font-size="90">${fav}</text></svg>`)}` : "icon.svg"; }
  const st = document.documentElement.style;
  st.setProperty("--accent", a);
  st.setProperty("--accent-soft", rgba(a, dark?.18:.12));
  st.setProperty("--accent-ink", contrast(a,"#ffffff")>=contrast(a,"#111111") ? "#ffffff" : "#111111");   // текст на кнопках
  document.querySelector('meta[name="theme-color"]').content = dark ? "#0e0d14" : "#f5f5f7";
  st.setProperty("--fz", LS.get("fz",1));
}
