// ================================================================ правки старосты (overrides)
function placeFromText(text, old){
  const m = /корп\S*\.?\s*(\S+?),?\s*ауд\S*\.?\s*(\S+)/i.exec(text||"");
  if(m){
    const bld=m[1].replace(/,$/,""), room=m[2].replace(/,$/,"");
    const addr = old && (old.ru||"").startsWith(`корп. ${bld},`) ? old.addr : "";
    return {ru:`корп. ${bld}, ауд. ${room}`, zh:`${bld}号楼 ${room}教室`, addr, map: old && addr ? old.map : text};
  }
  return {ru:text, zh:text, addr:"", map:text};
}
// дистанционные пары: «video» — видеолекция (запись), «live» — онлайн с преподавателем (в т.ч. зачёты).
// Показ — по настройке студента; пара с правкой старосты («показать всем» или любая правка) видна всем.
const onlineMode = () => LS.get("online","live")==="all" ? "all" : "live";   // live — очные и онлайн (всегда), all — плюс видеолекции
function onlineVisible(l, forStudents=false){
  if(!l.online) return true;
  if(l.ov && l.ov.action!=="cancel") return true;
  const m=onlineMode();
  const ok = m==="all" || (m==="live" && l.online==="live");
  if(forStudents) return l.online==="live";   // что видят студенты по умолчанию — для пометки старосте
  return ok || (typeof devMode==="function" && devMode());
}
function applyOverrides(g){
  const items = OVR.filter(o=>String(o.g)===String(g.id) && (!o.hold || devMode())), out = [];
  for(const l of g.lessons){
    const o = items.find(o=>o.action!=="add" && o.date===l.date && o.start===l.start && o.subj===l.subject.ru);
    const base = {...l, ostart:l.start};
    if(!o){ out.push(base); continue; }
    const n = {...base, ov:{...o, was:`${l.start}–${l.end}, ${tr(l.place)}`}};
    if(o.action==="change"){
      if(o.start2) n.start=o.start2;
      if(o.end2) n.end=o.end2;
      if(o.place && o.place!==l.place.ru) n.place=placeFromText(o.place, l.place);
      if(o.teacher){ n.teachers=[{ru:o.teacher, zh:o.teacher}]; n.ov.was += " · "+(l.teachers||[]).map(x=>tr(x)).join(", "); }
    }
    out.push(n);
  }
  const subjZh = ru => (g.lessons.find(x=>x.subject.ru===ru)||{subject:{zh:ru}}).subject.zh;
  for(const o of items.filter(o=>o.action==="add")){
    const t = o.type || "Практика";
    out.push({date:o.date, start:o.start, end:o.end2||o.start, ostart:o.start, subject:{ru:o.subj, zh:subjZh(o.subj)},
      type:{ru:t, zh:TYPE_ZH[t]||t}, kind:/^(Зачёт|Экзамен)/.test(t)?"exam":(t==="Консультация"?"consult":""),
      teachers:o.teacher?[{ru:o.teacher, zh:o.teacher}]:[], place:placeFromText(o.place||""), ov:{...o}});
  }
  out.sort((a,b)=> a.date<b.date?-1:a.date>b.date?1: toMin(a.start)-toMin(b.start));
  return out;
}
