// ================================================================ личное: заметки, пропуски, контакты, кодовые слова
const notes = () => LS.get("notes", {});
const absents = () => LS.get("absent", {});
const myContacts = () => LS.get("myContacts", {});
const noteKey = (gid,l) => `${gid}|${l.date}|${l.ostart||l.start}|${l.subject.ru}`;
const countable = l => !(l.ov && l.ov.action==="cancel") && l.kind!=="exam" && l.kind!=="consult" && l.online!=="video";
const started = (l, ctx) => l.date<ctx.today || (l.date===ctx.today && ctx.now>=toMin(l.start));

