const hwAll = () => LS.get("hw", []).sort((a,b)=>(a.due||"9")<(b.due||"9")?-1:1);
// архив: сделанные (со следующего дня), просроченные больше недели и убранные вручную
const isArch = (h, today=spbNow().today) => h.arch===true || (h.arch!==false && ((h.done && (h.doneAt||"")<today) || (!h.done && h.due && h.due<addDays(today,-7))));
const hwLive = () => hwAll().filter(h=>!isArch(h));
const hwFor = (ru, date) => hwAll().filter(h=>h.subj===ru && h.due===date);
function nextLessonDate(ru, after){   // null — у предмета больше нет пар
  const l = active(myGroup().lessons).find(x=>x.subject.ru===ru && x.date>after);
  return l ? l.date : null;
}
function hwSubjChange(){   // сменили предмет — «к следующей паре» считаем уже по нему
  if(!hwDraft) return; hwDraft.next=nextLessonDate($("hw_s").value, hwDraft.from||spbNow().today);
  if(hwDraft.mode==="next"){ if(hwDraft.next) hwDraft.due=hwDraft.next; else { hwDraft.mode="none"; hwDraft.due=""; } }
  keepHw();
}
function hwRow(h, ctx){
  const t=L(), subj=(allSubjects().find(x=>x.ru===h.subj)||{ru:h.subj,zh:h.subj}), late=!h.done && h.due && h.due<ctx.today;
  return `<div class="hwrow ${h.done?"done":""}" style="${subjStyle(h.subj)}"><input type="checkbox" data-act="hwDone" data-v="${h.id}" ${h.done?"checked":""}>
    <button class="hwtxt" data-act="hwEdit" data-v="${h.id}"><b>${esc(h.text)}</b><small>${esc(tr(subj))}${h.due?` · <span class="${late?"late":""}">${late?t.hwLate+" · ":""}${t.hwDue} ${fmtDay(h.due).d}</span>`:""}${(h.files||[]).length?` · 📎 ${h.files.length}`:""}</small></button></div>`;
}
// предметы текущего семестра (осень: сентябрь–январь, весна: февраль–июль)
function semesterSubjects(ctx){
  const y=+ctx.today.slice(0,4), m=+ctx.today.slice(5,7);
  const [from,to] = m>=9 ? [`${y}-09-01`,`${y+1}-01-31`] : m===1 ? [`${y-1}-09-01`,`${y}-01-31`] : [`${y}-02-01`,`${y}-08-31`];
  const seen=new Map();
  for(const l of myGroup().lessons) if(l.date>=from && l.date<=to && !seen.has(l.subject.ru)) seen.set(l.subject.ru, l.subject);
  return [...seen.values()].sort((a,b)=>tr(a).localeCompare(tr(b),Z()?"zh":"ru"));
}
function tasksScreen(ctx){
  const t=L(), subs=semesterSubjects(ctx), f=state.hwSubj;
  if(state.hwArch) return archScreen(ctx);
  const allAll=hwLive(), arch=hwAll().filter(h=>isArch(h,ctx.today)&&(!f||h.subj===f)), all=allAll.filter(h=>!f||h.subj===f).slice().sort((a,b)=>(a.due||"9")<(b.due||"9")?-1:1), open=all.filter(h=>!h.done), done=all.filter(h=>h.done);
  const cnt = ru => allAll.filter(h=>!h.done && h.subj===ru).length;
  const cur = f ? (subs.find(x=>x.ru===f)||{ru:f,zh:f}) : null;
  let h = `<p class="muted small intro snowhost">${t.hwIntro}${snowSpot("tasks")}</p><div class="hwtop"><button class="subjsel" data-act="subjPick">${cur?`<i class="sdot" style="background:${colorOf(f)}"></i>`:icon("tasks","sm")}<span>${cur?esc(tr(cur)):t.hwAllSubj}</span>${icon("chev","sm cdown")}</button>
      <button class="nav" data-act="openRemind" aria-label="${t.remSet}">${icon("bell")}</button></div>
    <button class="btn wide" data-act="hwNew">${icon("plus","sm")} ${t.hwAdd}${f?` · ${esc(tr(subs.find(x=>x.ru===f)||{ru:f,zh:f}))}`:""}</button>`;
  const archBtn = `<button class="secbtn" data-act="hwArchOpen"><span>🗄 ${t.hwArch}${arch.length?" · "+arch.length:""}</span>${icon("chev","sm")}</button>`;
  if(!all.length) return h + `<div class="empty">${f?t.hwEmptySubj:t.hwEmpty}</div>` + (arch.length?archBtn:"");
  const late=open.filter(x=>x.due && x.due<ctx.today), soon=open.filter(x=>x.due && x.due>=ctx.today), nodue=open.filter(x=>!x.due);
  if(late.length) h += `<h3 class="late">${t.hwLateT} · ${late.length}</h3>` + late.map(x=>hwRow(x,ctx)).join("");
  if(soon.length) h += `<h3>${t.hwOpen} · ${soon.length}</h3>` + soon.map(x=>hwRow(x,ctx)).join("");
  if(nodue.length) h += `<h3>${t.hwNoDueT} · ${nodue.length}</h3>` + nodue.map(x=>hwRow(x,ctx)).join("");
  if(done.length) h += `<h3>${t.hwDone} · ${done.length}</h3>` + done.map(x=>hwRow(x,ctx)).join("");
  return h + archBtn;
}
function archScreen(ctx){
  const t=L(), f=state.hwSubj, subs=allSubjects();
  const list=hwAll().filter(h=>isArch(h,ctx.today)&&(!f||h.subj===f)).sort((a,b)=>((b.due||b.doneAt||"")>(a.due||a.doneAt||"")?1:-1));
  let h=`<p class="muted small intro">${t.hwArchIntro}</p>${f?`<button class="subjsel" data-act="subjPick"><i class="sdot" style="background:${colorOf(f)}"></i><span>${esc(tr(subs.find(x=>x.ru===f)||{ru:f,zh:f}))}</span>${icon("chev","sm cdown")}</button>`:""}`;
  if(!list.length) return h+`<div class="empty">${t.hwArchEmpty}</div>`;
  const sel=state.archSel;   // null — обычный режим, Set — режим выбора
  h += `<div class="btnrow archbar">${sel?`<button class="btn small ghost" data-act="archSelAll">${t.hwSelAll}</button><button class="btn small danger" data-act="archSelDel" ${sel.size?"":"disabled"}>${t.hwSelDel(sel.size)}</button><button class="btn small ghost" data-act="archSel">${t.cancel2}</button>`
    :`<button class="btn small ghost" data-act="archSel">☑︎ ${t.hwSel}</button>`}</div>`;
  h += list.map(x=>{ const subj=subs.find(z=>z.ru===x.subj)||{ru:x.subj,zh:x.subj};
    return `<div class="hwrow arch" style="${subjStyle(x.subj)}">${sel?`<input type="checkbox" data-act="archTick" data-v="${x.id}" ${sel.has(x.id)?"checked":""}>`:""}<button class="hwtxt" data-act="${sel?"archTickRow":"hwEdit"}" data-v="${x.id}"><b>${esc(x.text)}</b><small>${esc(tr(subj))}${x.due?` · ${t.hwDue} ${fmtDay(x.due).d}`:""} · <span class="${x.done?"okc":"late"}">${x.done?"✓ "+t.hwDoneMark:t.hwNotDone}</span>${(x.files||[]).length?` · 📎 ${x.files.length}`:""}</small></button>
      ${sel?"":`<button class="btn small ghost" data-act="hwRestore" data-v="${x.id}">${t.hwRestore}</button>`}</div>`; }).join("");
  return h + (sel?"":`<div class="btnrow"><button class="btn small ghost dangert" data-act="hwArchClear">${t.hwArchClear}</button></div>`);
}
// файлы заданий хранятся в IndexedDB этого телефона (фото сжимаются)
const FDB = () => new Promise((ok,fail)=>{ const r=indexedDB.open("raspisanie",1); r.onupgradeneeded=()=>r.result.createObjectStore("files"); r.onsuccess=()=>ok(r.result); r.onerror=()=>fail(r.error); });
async function fPut(id, blob){ const db=await FDB(); return new Promise(ok=>{ const tx=db.transaction("files","readwrite"); tx.objectStore("files").put(blob,id); tx.oncomplete=ok; }); }
async function fGet(id){ const db=await FDB(); return new Promise(ok=>{ const q=db.transaction("files").objectStore("files").get(id); q.onsuccess=()=>ok(q.result); q.onerror=()=>ok(null); }); }
async function fDel(id){ const db=await FDB(); db.transaction("files","readwrite").objectStore("files").delete(id); }
async function shrinkImage(file){
  try{ const bmp=await createImageBitmap(file), k=Math.min(1,1600/Math.max(bmp.width,bmp.height)), c=document.createElement("canvas");
    c.width=Math.round(bmp.width*k); c.height=Math.round(bmp.height*k); c.getContext("2d").drawImage(bmp,0,0,c.width,c.height);
    return await new Promise(ok=>c.toBlob(b=>ok(b||file),"image/jpeg",.82)); }catch(e){ return file; }
}
let hwDraft=null;   // черновик открытого задания: {files:[{id,name,type}], due, dueMode}
function hwFilesHTML(){
  return (hwDraft.files||[]).map(f=>`<div class="hwfile" data-fid="${f.id}">${/^image/.test(f.type)?`<img data-thumb="${f.id}" alt="">`:/^video/.test(f.type)?`<span class="fi">🎬</span>`:`<span class="fi">📄</span>`}
    <button class="fopen" data-act="hwOpenFile" data-v="${f.id}">${esc(f.name)}</button><button class="fx" data-act="hwRmFile" data-v="${f.id}">${icon("x","sm")}</button></div>`).join("");
}
