  const shareB = ctx.gid ? `<button class="daysh" data-act="dayNote" data-v="${date}" aria-label="${t.dnTitle}">${icon("note","sm")}</button>`+(ls.length?`<button class="daysh" data-act="sharePick" data-v="${date}" aria-label="${t.shDay}">${icon("share","sm")}</button>`:"") : "";
  let h = head ? `<div class="dayhead ${date===ctx.today?"today":""}"><span class="d">${dayW(f)}</span>${tag?`<span class="tag">${tag}</span>`:""}${add}${shareB}</div>` : (add||shareB?`<div class="dayhead">${add}${shareB}</div>`:"");
