function nextBarHTML(g, ctx){
  const t=L(), ls=active(g.lessons), today=ls.filter(l=>l.date===ctx.today);
  const cur = today.find(l=>ctx.now>=toMin(l.start) && ctx.now<toMin(l.end));
  const where = l => esc(tr(l.place));
  let a,b,c="",st="";
  if(cur){ a=`● ${t.nowIs} · ${t.left} ${fmtGap(toMin(cur.end)-ctx.now)}`; b=esc(tr(cur.subject)); c=where(cur); st=subjStyle(cur.subject.ru);
    c += `<div class="pbar"><div style="width:${Math.round((ctx.now-toMin(cur.start))/(toMin(cur.end)-toMin(cur.start))*100)}%"></div></div>`; }
  else{
    const nx = today.find(l=>toMin(l.start)>ctx.now);
    if(nx){ a=`${t.nextIn} ${fmtGap(toMin(nx.start)-ctx.now)}`; b=esc(tr(nx.subject)); c=`${nx.start} · ${where(nx)}`; st=subjStyle(nx.subject.ru); }
    else{
      const tm = ls.filter(l=>l.date===addDays(ctx.today,1));
      a = today.length ? t.todayDone : t.noToday; b = tm.length ? `${t.tmrFirst} ${tm[0].start}` : t.noTmr;
      if(tm.length){ c = `${esc(tr(tm[0].subject))} · ${where(tm[0])}`; st=subjStyle(tm[0].subject.ru); }
    }
  }
  return `<button class="hero" style="${st}"><div class="t1">${a}</div><div class="t2">${b}</div>${c?`<div class="t3">${c}</div>`:""}</button>`;
}
