// ================================================================ картинка дня (для WeChat и галереи)
function wrapText(ctx, text, maxW){
  const words=String(text).split(/(\s+)/), lines=[]; let cur="";
  const pushChars = w => { for(const ch of w){ if(ctx.measureText(cur+ch).width>maxW && cur){ lines.push(cur); cur=ch; } else cur+=ch; } };
  for(const w of words){
    if(ctx.measureText(cur+w).width<=maxW){ cur+=w; continue; }
    if(cur.trim()) lines.push(cur.trim()); cur="";
    if(ctx.measureText(w).width>maxW) pushChars(w); else cur=w.trimStart();
  }
  if(cur.trim()) lines.push(cur.trim()); return lines;
}
async function dayImage(date){
  const g=myGroup(), ls=active(g.lessons).filter(l=>l.date===date), z=Z(), f=fmtDay(date);
  const W=1080, P=56, F='-apple-system,"PingFang SC","AppInter","Microsoft YaHei","Segoe UI",Roboto,sans-serif';
  const c=document.createElement("canvas"), x=c.getContext("2d"); c.width=W; c.height=4000;
  const acc=getComputedStyle(document.documentElement).getPropertyValue("--accent").trim()||"#5b4bdb";
  x.fillStyle="#f5f5f7"; x.fillRect(0,0,W,4000);
  let y=P;
  x.fillStyle=acc; x.font=`800 30px ${F}`; x.fillText(`${z?"课程表":"Расписание"} · ${g.label}`, P, y+30); y+=62;
  x.fillStyle="#1c1c1e"; x.font=`800 56px ${F}`; x.fillText(`${dayW(f)}`, P, y+50); y+=90;
  if(!ls.length){ x.font=`600 40px ${F}`; x.fillStyle="#8e8e93"; x.fillText(L().freeDay, P, y+40); y+=90; }
  let prev=null;
  for(const l of ls){
    if(prev!==null && toMin(l.start)-prev>10){ x.font=`700 30px ${F}`; x.fillStyle="#c26a00"; x.fillText(`☕ ${L().brk} ${fmtGap(toMin(l.start)-prev)}`, P+20, y+34); y+=58; }
    const col=colorOf(l.subject.ru), tx=P+170, tw=W-P-tx-24;
    x.font=`800 40px ${F}`; const sl=wrapText(x, (l.kind==="exam"?"‼️ ":"")+tr(l.subject), tw);
    x.font=`500 30px ${F}`; const pl=wrapText(x, "📍 "+(z?l.place.zh:l.place.ru)+(l.place.addr?(z?`（${l.place.addr}）`:` · ${l.place.addr}`):""), tw);
    const who=(l.teachers||[]).map(fullName).join(z?"、":", "), wl = who ? wrapText(x, "👤 "+who, tw) : [];
    const h = 36 + sl.length*50 + 44 + pl.length*40 + wl.length*40 + 30;
    x.fillStyle="#fff"; x.beginPath(); x.roundRect(P,y,W-2*P,h,28); x.fill();
    x.fillStyle=col; x.beginPath(); x.roundRect(P,y,14,h,[28,0,0,28]); x.fill();
    x.fillStyle=rgba(col,.12); x.beginPath(); x.roundRect(P+14,y,W-2*P-14,h,[0,28,28,0]); x.fill();
    x.fillStyle="#1c1c1e"; x.font=`800 40px ${F}`; x.fillText(l.start, P+36, y+62);
    x.fillStyle="#8e8e93"; x.font=`500 32px ${F}`; x.fillText(l.end, P+36, y+104);
    let yy=y+36+40; x.fillStyle="#1c1c1e"; x.font=`800 40px ${F}`; for(const s of sl){ x.fillText(s, tx, yy); yy+=50; }
    x.fillStyle= l.kind==="exam"?"#e5484d":"#6f6c85"; x.font=`700 30px ${F}`; x.fillText(tr(l.type), tx, yy); yy+=44;
    x.fillStyle="#3c3c43"; x.font=`500 30px ${F}`; for(const s of pl){ x.fillText(s, tx, yy); yy+=40; } for(const s of wl){ x.fillText(s, tx, yy); yy+=40; }
    y += h + 20; prev=toMin(l.end);
  }
  y+=30;   // без ссылки на сайт: картинка — только расписание
  const out=document.createElement("canvas"); out.width=W; out.height=y; out.getContext("2d").drawImage(c,0,0);
  return new Promise(ok=>out.toBlob(ok,"image/png"));
}
