// картинка недели: дни подряд, компактно
async function weekImage(mon){
  const g=myGroup(), z=Z(), W=1080, P=48, F='-apple-system,"PingFang SC","AppInter","Microsoft YaHei","Segoe UI",Roboto,sans-serif';
  const c=document.createElement("canvas"), x=c.getContext("2d"); c.width=W; c.height=6000;
  const acc=getComputedStyle(document.documentElement).getPropertyValue("--accent").trim()||"#5b4bdb";
  x.fillStyle="#f5f5f7"; x.fillRect(0,0,W,6000);
  let y=P;
  x.fillStyle=acc; x.font=`800 30px ${F}`; x.fillText(`${z?"课程表":"Расписание"} · ${g.label}`, P, y+30); y+=58;
  x.fillStyle="#1c1c1e"; x.font=`800 50px ${F}`; x.fillText(`${fmtDay(mon).d} — ${fmtDay(addDays(mon,6)).d}`, P, y+46); y+=84;
  for(let i=0;i<7;i++){
    const d=addDays(mon,i), ls=active(g.lessons).filter(l=>l.date===d); if(!ls.length) continue;
    const f=fmtDay(d); x.fillStyle=acc; x.font=`800 36px ${F}`; x.fillText(`${dayW(f)}`, P, y+36); y+=56;
    for(const l of ls){
      const col=colorOf(l.subject.ru), tx=P+150, tw=W-P-tx-20;
      x.font=`700 32px ${F}`; const sl=wrapText(x,(l.kind==="exam"?"‼️ ":"")+tr(l.subject)+" · "+tr(l.type), tw);
      x.font=`500 27px ${F}`; const pl=wrapText(x,"📍 "+(z?l.place.zh:l.place.ru)+(l.place.addr?(z?`（${l.place.addr}）`:` · ${l.place.addr}`):""), tw);
      const h=24+sl.length*40+pl.length*34+18;
      x.fillStyle="#fff"; x.beginPath(); x.roundRect(P,y,W-2*P,h,22); x.fill();
      x.fillStyle=col; x.beginPath(); x.roundRect(P,y,12,h,[22,0,0,22]); x.fill();
      x.fillStyle="#1c1c1e"; x.font=`800 32px ${F}`; x.fillText(l.start, P+30, y+50);
      x.fillStyle="#8e8e93"; x.font=`500 26px ${F}`; x.fillText(l.end, P+30, y+84);
      let yy=y+24+30; x.fillStyle="#1c1c1e"; x.font=`700 32px ${F}`; for(const s of sl){ x.fillText(s,tx,yy); yy+=40; }
      x.fillStyle="#3c3c43"; x.font=`500 27px ${F}`; for(const s of pl){ x.fillText(s,tx,yy); yy+=34; }
      y+=h+14;
    }
    y+=16;
  }
  y+=16;
  const out=document.createElement("canvas"); out.width=W; out.height=y; out.getContext("2d").drawImage(c,0,0);
  return new Promise(ok=>out.toBlob(ok,"image/png"));
}
