const userSeed = () => { const a=acct(); if(a) return a.id; let s=localStorage.getItem("seed"); if(!s){ s=Math.random().toString(36).slice(2); localStorage.setItem("seed", s); } return s; };
const pickU = (arr, salt) => { let h=2166136261; for(const c of userSeed()+"|"+salt) h=Math.imul(h^c.charCodeAt(0),16777619)>>>0;
  h^=h>>>16; h=Math.imul(h,0x85ebca6b)>>>0; h^=h>>>13; h=Math.imul(h,0xc2b2ae35)>>>0; h^=h>>>16; return arr[(h>>>0)%arr.length]; };
// у каждого свой порядок (перемешан по номеру устройства/аккаунта), день за днём без повторов, пока список не кончится
function pickSeq(arr, salt, n){
  let h=2166136261; for(const c of userSeed()+"|"+salt) h=Math.imul(h^c.charCodeAt(0),16777619)>>>0;
  const rnd=()=>{ h^=h<<13; h>>>=0; h^=h>>>17; h^=h<<5; h>>>=0; return h/4294967296; };
  const idx=arr.map((_,i)=>i); for(let i=idx.length-1;i>0;i--){ const j=Math.floor(rnd()*(i+1)); [idx[i],idx[j]]=[idx[j],idx[i]]; }
  return arr[idx[((n%arr.length)+arr.length)%arr.length]];
}
const pickDay = (arr, salt) => { let h=7; for(const c of spbNow().today+salt) h=(h*31+c.charCodeAt(0))>>>0; return arr[h%arr.length]; };
