    <div class="pick mgpick">${MG_TAGS.map(x=>{ const w=Z()?x[1]:x[0]; return `<button data-act="mgTag" data-v="${esc(w)}" class="${sel.includes(w)?"on":""}">${esc(w)}</button>`; }).join("")}
      ${sel.filter(w=>!MG_TAGS.some(x=>x[0]===w||x[1]===w)).map(w=>`<button data-act="mgTag" data-v="${esc(w)}" class="on">${esc(w)} ✕</button>`).join("")}</div>
