function mgFire(){
  const e=$("effigy"), sel=(state.mgTags||[]).slice(); if(!e||!sel.length) return;
  const btn=$("sheet").querySelector("[data-act=mgFire]"); if(btn) btn.disabled=true;
  const finish=()=>{ state.mgDone=sel; state.mgTags=[]; LS.set("mgBurnN", LS.get("mgBurnN",0)+1); refreshSheet(); };
  if(!animOn()) return finish();
  if(navigator.vibrate) navigator.vibrate([30,60,30]);
  e.classList.add("burning");
  const cv=e.querySelector(".firecv"), cx=cv.getContext("2d"), dpr=Math.min(2,window.devicePixelRatio||1);
  const W=cv.clientWidth, H=cv.clientHeight; cv.width=W*dpr; cv.height=H*dpr; cx.setTransform(dpr,0,0,dpr,0,0);
  // мягкие «пятна» света трёх цветов — из них складывается пламя (рисуем с режимом сложения света)
  const sprite=(r,g,b)=>{ const c=document.createElement("canvas"); c.width=c.height=64; const x=c.getContext("2d"), gr=x.createRadialGradient(32,32,0,32,32,32);
    gr.addColorStop(0,`rgba(${r},${g},${b},1)`); gr.addColorStop(.35,`rgba(${r},${g},${b},.55)`); gr.addColorStop(1,`rgba(${r},${g},${b},0)`); x.fillStyle=gr; x.fillRect(0,0,64,64); return c; };
  const S=[sprite(255,244,214),sprite(255,190,70),sprite(255,110,25),sprite(200,40,10)], SMOKE=sprite(90,80,80);
  // чучело внутри холста: холст шире и выше картинки (см. CSS), здесь — границы соломенного тела
  const ox=(W-180)/2, oy=H-8-300, k=1.5, cxm=ox+60*k;
  const halfW=yv=>{ if(yv<24) return 0; if(yv<58) return 15*k; if(yv<96) return (16+(yv-58)*.35)*k; return Math.min(36,(30+(yv-96)*.12))*k; };   // ширина тела на высоте yv (в единицах рисунка)
  const P=[], t0=performance.now(); let last=t0, notesGone=false;
  function frame(now){
    const t=(now-t0)/1000, dt=Math.min(.05,(now-last)/1000); last=now;
    // огонь поднимается снизу вверх, потом утихает
    const front = Math.min(1, t/1.6), power = t<2.6 ? Math.min(1,t/.4) : Math.max(0,1-(t-2.6)/1.1);
    const n = Math.round(power*16*dt*60);
    for(let q=0;q<n;q++){
      const yv = 196 - Math.pow(Math.random(),1.35)*front*176, hw=halfW(yv); if(!hw && yv>24) continue;
      const x = cxm + (Math.random()*2-1)*(hw||12*k), y = oy + yv*k;
      P.push({x, y, vx:(Math.random()-.5)*18, vy:-(70+Math.random()*90), life:0, max:.5+Math.random()*.5, r:13+Math.random()*10, smoke:false});
    }
    if(power>.2 && Math.random()<power*.9) P.push({x:cxm+(Math.random()-.5)*60, y:oy+(196-front*170)*k, vx:(Math.random()-.5)*14, vy:-(40+Math.random()*30), life:0, max:1.6+Math.random(), r:16+Math.random()*14, smoke:true});
    if(power>.3 && Math.random()<.5) P.push({x:cxm+(Math.random()-.5)*80, y:oy+(150-front*100)*k, vx:(Math.random()-.5)*60, vy:-(120+Math.random()*120), life:0, max:.8+Math.random()*.9, r:1.6+Math.random()*1.4, spark:true});
    cx.clearRect(0,0,W,H);
    // дым — обычными слоями, под огнём
    cx.globalCompositeOperation="source-over";
    for(const p of P) if(p.smoke){ const a=p.life/p.max; cx.globalAlpha=.28*(1-a)*Math.min(1,a*4); const r=p.r*(1+a*2.2); cx.drawImage(SMOKE,p.x-r,p.y-r,r*2,r*2); }
    // пламя и искры — сложением света: где частиц много, там ярче и белее
    cx.globalCompositeOperation="lighter";
    for(const p of P){ if(p.smoke) continue; const a=p.life/p.max;
      if(p.spark){ cx.globalAlpha=(1-a)*(.6+.4*Math.sin(now/40+p.x)); cx.drawImage(S[1],p.x-p.r*3,p.y-p.r*3,p.r*6,p.r*6); continue; }
      const spr = a<.15?S[0] : a<.4?S[1] : a<.7?S[2] : S[3], r=p.r*(1-a*.7);
      cx.globalAlpha=Math.min(1,(1-a)*1.1)*.24; cx.drawImage(spr,p.x-r,p.y-r*1.7,r*2,r*3.4); }
    cx.globalAlpha=1; cx.globalCompositeOperation="source-over";
    for(const p of P){ p.life+=dt; p.x+=p.vx*dt+Math.sin(p.life*9+p.y*.05)*(p.smoke?.3:.6); p.y+=p.vy*dt; if(!p.smoke&&!p.spark) p.vx*=.98; }
    for(let q=P.length-1;q>=0;q--) if(P[q].life>=P[q].max) P.splice(q,1);
    if(!notesGone && t>.7){ notesGone=true; e.classList.add("charred"); }
    if(t<4.2 || P.length) requestAnimationFrame(frame); else finish();
  }
  requestAnimationFrame(frame);
}

function moonCardHTML(){
  if(!moonDecor()) return "";
  const t=L(), f=pickSeq(MOON_FACT,"mf"+spbNow().today.slice(0,4), daysBetween(MOON_DATES.find(x=>Math.abs(daysBetween(x,spbNow().today))<=10)||spbNow().today, spbNow().today)+5);
  return `<div class="card hbcard moon"><span class="hbico">🥮</span><span><b>${t.moonT}</b><small>${esc(Z()?f[1]:f[0])}</small></span></div>`;
}
