// какой праздник «скоро» и через сколько дней (только дни, когда его тема уже включена)
function preKey(d){
  const md=d.slice(5), y=+d.slice(0,4), till=x=>daysBetween(d,x);
  if(md==="01-24") return ["tatPre",1];
  if(md==="02-12"||md==="02-13") return ["valPre",till(`${y}-02-14`)];
  if(md==="02-22") return ["feb23Pre",1];
  if(md==="03-06"||md==="03-07") return ["mar8Pre",till(`${y}-03-08`)];
  if(md==="11-16") return ["studPre",1];
  if(md>="12-01"&&md<="12-30") return ["nyPre",till(`${y+1}-01-01`)];
  if(md>="10-06"&&md<="10-30") return ["hallPre",till(`${y}-10-31`)];
  for(const x of CNY_DATES){ const n=till(x); if(n>=1&&n<=10) return ["cnyPre",n]; }
  for(const x of MOON_DATES){ const n=till(x); if(n>=1&&n<=5) return ["moonPre",n]; }
  return null;
}
// у Хэллоуина и Китайского Нового года тема держится долго — фраза не каждый день:
// при первом заходе после включения темы (пока не закрыли) и в последние 3 дня перед праздником
const PRE_LONG=["hallPre","cnyPre"], PRE_LAST=3;
function preFirstSeen(k, d){
  const n=(preKey(d)||[k,0])[1], target=addDays(d,n);
  return (LS.get("greetSeen",[])||[]).some(e=>{ const [x,kk]=e.split(":"); return kk===k && x<d && daysBetween(x,target)>PRE_LAST; });
}
function preText(k, d, en=0){
  const P=PRE_HOL[k], n=(preKey(d)||[k,1])[1], z=Z(), salt=k+addDays(d,n).slice(0,4), i=(PRE_LONG.includes(k)&&n>PRE_LAST ? 0 : n)+en;   // соседние дни и каждый заход — разные фразы
  const Nom=P.nom[0].toUpperCase()+P.nom.slice(1), dn=`${n} ${plural(n,"день","дня","дней")}`;
  const first = PRE_LONG.includes(k) && n>PRE_LAST;
  const o = first ? (z?`${P.zh}快到了，应用换上了节日装扮！离节日还有${n}天。`:`${Nom} уже скоро, поэтому в приложении праздничное оформление! До праздника ${dn}.`)
    : n===1 ? (z?`明天就是${P.zh}啦！`:`Завтра ${P.nom}!`)
    : n===2 ? (z?`后天就是${P.zh}啦！`:`Послезавтра ${P.nom}!`)
    : pickSeq(z?[`离${P.zh}还有${n}天！`,`还有${n}天就是${P.zh}啦！`]:[`До ${P.gen} ${dn}!`,`${Nom} уже через ${dn}!`], salt+"o", i);
  const m=pickSeq(P.m, salt+"m", i)[z?1:0], c=pickSeq(P.c, salt+"c", i)[z?1:0];
  return z ? o+m+c : `${o} ${m} ${c}`;
}
function greetKey(d){
  const md=d.slice(5);
  if(md==="12-31") return "ny31"; if(md==="01-01") return "ny1"; if(md==="01-25") return "tat"; if(md==="02-14") return "val"; if(md==="03-08") return "mar8";
  if(md==="04-01") return "fool"; if(md==="09-01") return "sep1"; if(md==="09-10") return "teachCn"; if(md==="10-05") return "teachRu"; if(md==="10-31") return "hall"; if(md==="11-17") return "stud";
  if(md==="02-23") return "feb23"; if(md==="05-09") return "may9";
  if(d===bfDate(+d.slice(0,4))) return "bf";
  if(MASL_DATES.some(x=>addDays(x,6)===d)) return "masl";
  if(MASL_DATES.some(x=>x===d && x.slice(5)!=="03-08") || MASL_DATES.some(x=>x.slice(5)==="03-08" && addDays(x,1)===d)) return "maslHi";
  if(CNY_DATES.includes(d)) return "cny"; if(MOON_DATES.includes(d)) return "moon"; const p=preKey(d); if(!p) return "";
  if(PRE_LONG.includes(p[0]) && p[1]>PRE_LAST && preFirstSeen(p[0], d)) return "";
  return p[0];
}
