// что говорит тыква: по кругу без повторов, часть фраз — про ваше расписание
function pumpkinLine(){
  const t=L(), g=myGroup(), ctx=spbNow(), all=active(g.lessons||[]);
  const day=Math.max(1, Math.min(31, +ctx.today.slice(8,10) + (ctx.today.slice(5,7)==="11"?31:0)));
  const open=Math.min(t.pkSay.length, 10 + (day-1)*2);
  const nx=all.find(l=>l.date>ctx.today || (l.date===ctx.today && toMin(l.start)>ctx.now));
  const tom=all.filter(l=>l.date===addDays(ctx.today,1)).length, hw=hwLive().filter(x=>!x.done).length;
  const live=[nx?t.pkNext(tr(nx.subject), nx.date===ctx.today?t.today.toLowerCase():fmtDay(nx.date).d):"", tom?t.pkTom(tom):t.pkTomFree, hw?t.pkHw(hw):t.pkHwNone];
  // каждая третья фраза — про ваше расписание
  const n=(LS.get("pkN",0)||0)+1; LS.set("pkN", n);
  const lv=live.filter(Boolean); if(n%3===0 && lv.length) return lv[Math.floor(Math.random()*lv.length)];
  let seen=LS.get("pkSeen",[]); if(!Array.isArray(seen)) seen=[];
  let left=[...Array(open).keys()].filter(i=>!seen.includes(i)); if(!left.length){ seen=[]; left=[...Array(open).keys()]; }
  const fresh=left.filter(i=>i>=open-2); const pickFrom = fresh.length && Math.random()<.5 ? fresh : left;   // новые за сегодня — почаще
  const i=pickFrom[Math.floor(Math.random()*pickFrom.length)]; LS.set("pkSeen", [...seen, i]); return t.pkSay[i];
}
