// картинка с предсказанием — поделиться или сохранить
function hbCanvas(){
  const p=hbWish(), c=document.createElement("canvas"); c.width=720; c.height=960;
  const x=c.getContext("2d"); const g=x.createLinearGradient(0,0,0,960); g.addColorStop(0,"#f25542"); g.addColorStop(1,"#c8352b"); x.fillStyle=g; x.fillRect(0,0,720,960);
  x.fillStyle="rgba(0,0,0,.08)"; x.beginPath(); x.ellipse(360,0,520,330,0,0,Math.PI); x.fill();
  x.textAlign="center"; x.textBaseline="middle";
  x.fillStyle="#f8dda5"; x.font="bold 130px serif"; x.fillText(p[0],360,420);
  x.font="34px sans-serif"; x.fillStyle="#ffe9c2"; x.fillText(p[1],360,515);
  const wrap=(txt,y,size,color)=>{ x.fillStyle=color; x.font=`${size}px sans-serif`; const cjk=/[\u4e00-\u9fff]/.test(txt), parts=cjk?[...txt]:txt.split(" "); let line="", lines=[];
    for(const w of parts){ const test=line+(line&&!cjk?" ":"")+w; if(x.measureText(test).width>600&&line){ lines.push(line); line=w; } else line=test; } lines.push(line);
    lines.forEach((l,i)=>x.fillText(l,360,y+i*size*1.35)); return y+lines.length*size*1.35; };
  let y=wrap(p[2],620,34,"#fff"); wrap(p[3],y+20,32,"#ffe9c2");
  x.fillStyle="#ebcd99"; x.beginPath(); x.arc(360,190,60,0,7); x.fill(); x.fillStyle="#7a3b12"; x.font="bold 60px serif"; x.fillText("福",360,194);

  return c;
}
