// контакты, которыми староста поделилась лично (ссылка #tc=): файл tcs/<f>.json собирает scripts/seal.py при выкладке.
// Открыть его можно только вдвоём: ключ из ссылки + имя аккаунта, на которое выдан доступ (вход в аккаунт — по паролю).
// Пересланная ссылка без входа в этот аккаунт ничего не покажет. Файл пропал после того, как уже открывался, — доступ убран
let TCS=null, TCS_FOR=null;
async function tcsNameKey(linkKey, name){ const k=await crypto.subtle.importKey("raw", linkKey, {name:"HMAC", hash:"SHA-256"}, false, ["sign"]);
  return new Uint8Array(await crypto.subtle.sign("HMAC", k, te.encode("tcs-name|"+acctNorm(name)))); }
async function aesOpen(rawKey, u){ const k=await crypto.subtle.importKey("raw", rawKey, "AES-GCM", false, ["decrypt"]); return new Uint8Array(await crypto.subtle.decrypt({name:"AES-GCM", iv:u.slice(0,12)}, k, u.slice(12))); }
function loadTcs(){ const s=LS.get("tcShare",null), a=acct(), who=a&&a.name||"";
  if(TCS && TCS_FOR===who) return; TCS={}; TCS_FOR=who;
  if(!s || !/^[0-9a-f]{16}$/.test(s.f||"") || !s.k) return;
  if(!who){ if(sessionStorage.getItem("tcsNew")){ sessionStorage.removeItem("tcsNew"); toast(L().tcsLogin, L().acMenu, ()=>pushSheet(openAccount)); } return; }
  sfetch("tcs/"+s.f+".json?v="+Date.now(), true).then(async r=>{
    if(!r.ok){ if(r.status===404 && s.ok){ LS.del("tcShare"); render(); } return; }
    const box=JSON.parse(td.decode(r.bytes)), lk=b64Bytes(s.k.replace(/-/g,"+").replace(/_/g,"/")+"="), nk=await tcsNameKey(lk, who);
    let dk=null; for(const w of box.w||[]){ try{ dk=await aesOpen(nk, b64Bytes(w)); break; }catch(e){} }
    if(!dk){ if(sessionStorage.getItem("tcsNew")){ sessionStorage.removeItem("tcsNew"); toast(L().tcsWrong); } return; }
    if(TCS_FOR!==who) return;
    TCS=JSON.parse(td.decode(await aesOpen(dk, b64Bytes(box.d))))||{};
    if(!s.ok || localStorage.getItem("tcsDirty")){ localStorage.removeItem("tcsDirty"); LS.set("tcShare", {...s, ok:true}); }
    if(sessionStorage.getItem("tcsNew")){ sessionStorage.removeItem("tcsNew"); toast(L().tcsGot); }
    render(); refreshSheet(); }).catch(e=>console.warn("tcs", e)); }
