// Расписание преподавателя для наших групп берём из расписания самих групп (с правками старосты и последними изменениями),
// чтобы у группы и у преподавателя всегда было одно и то же. Для остальных групп — со страницы преподавателя на сайте Герцена.
function teacherMerged(id){
  const tt=TCACHE[id]; if(!tt) return null;
  const labels=DATA.groups.map(g=>g.label), ours=new Map();
  for(const g0 of DATA.groups){ const g=EG(g0); if(g.loading) continue;
    for(const l of g.lessons) if((l.teachers||[]).some(x=>String(x.id)===String(id))){
      const k=l.date+"|"+(l.ostart||l.start)+"|"+l.subject.ru, e=ours.get(k);
      if(e){ if(!e.groups.split(", ").includes(g.label)) e.groups+=", "+g.label; } else ours.set(k, {...l, groups:g.label, teachers:undefined}); } }
  const onlyOurs = l => { const gs=(l.groups||"").split(/,\s*/).filter(Boolean); return gs.length && gs.every(x=>labels.includes(x)); };
  const base = tt.lessons.filter(l=>!onlyOurs(l));
  for(const l of tt.lessons) if(onlyOurs(l)){   // аудитория подгруппы преподавателя точнее — берём её, если староста не меняла место
    const o=ours.get(l.date+"|"+l.start+"|"+l.subject.ru); if(o && !(o.ov && o.ov.action==="change")) o.place=l.place; }
  const lessons=[...base, ...ours.values()].sort((a,b)=>a.date<b.date?-1:a.date>b.date?1:toMin(a.start)-toMin(b.start));
  return {...tt, lessons, practices:[]};
}
