const ll2 = a => [a[1], a[0]];   // [широта, долгота] → [долгота, широта]
async function initMap(){
  const el=$("lmap"); if(!el) return;
  try{ await loadMapLib(); }catch(e){ el.innerHTML=emptyBox(L().mapOffline); return; }
  if(!CAMPUSDATA){ try{ CAMPUSDATA=await (await fetch("campus.json")).json(); }catch(e){ el.innerHTML=emptyBox(L().mapOffline); return; } }
  if(!$("lmap")) return;
  const ml=window.maplibregl, D=CAMPUSDATA, hl=state.mapHl, t=L();
  if(MAP){ MAP.remove(); MAP=null; }
  el.innerHTML=""; el.dataset.ready="1"; MAPEL=el; MAPKEY=mapKey();
  const center = hl==="32" ? ll2(D.ligovsky) : hl && D.corpus[hl] ? ll2(D.corpus[hl]) : ll2(D.stadium||D.corpus["2"]);
  MAP = new ml.Map({container:el, style:`https://tiles.openfreemap.org/styles/${isDark()?"dark":"liberty"}`, center, zoom: hl?17.4:16.6,
    pitch: MAP3D?55:0, bearing:0, attributionControl:{compact:true}, maxZoom:20});
  { let warned=false; MAP.on("error", ()=>{ if(warned) return; warned=true; const m=$("mapmsg"); if(m) m.insertAdjacentHTML("afterbegin", `<span class="maperr">⚠️ ${L().mapTilesErr}</span><br>`); }); }   // VPN/сеть: подложка не грузится — объясняем
  MAP.addControl(new ml.NavigationControl({visualizePitch:true}), "top-right");
  GEOCTL = new ml.GeolocateControl({positionOptions:{enableHighAccuracy:true}, trackUserLocation:true, showAccuracyCircle:true});
  MAP.addControl(GEOCTL, "top-right");
  GEOCTL.on("error", e=>{ const m=$("mapmsg"); if(m) m.textContent = e.code===1 ? t.mapGeoDenied : t.mapNoGeo; });
  MAP.on("load", ()=>{
    el.querySelectorAll(".maplibregl-compact-show").forEach(x=>x.classList.remove("maplibregl-compact-show"));   // свернуть подпись
    const acc = getComputedStyle(document.documentElement).getPropertyValue("--accent").trim() || "#5b4bdb";
    MAP.addSource("campus", {type:"geojson", data:{type:"Feature", geometry:{type:"Polygon", coordinates:[D.outline.map(ll2)]}}});
    MAP.addLayer({id:"campus-line", type:"line", source:"campus", paint:{"line-color":acc, "line-width":2.5, "line-opacity":.85}});
  });
  const mk = (ll, html, title, big) => { const d=document.createElement("div"); d.innerHTML=html; const e=d.firstChild; e.title=title;
    new ml.Marker({element:e}).setLngLat(ll2(ll)).setPopup(new ml.Popup({offset:big?24:16, closeButton:false}).setText(title)).addTo(MAP); return e; };
  for(const [n,ll] of Object.entries(D.corpus)){
    const on=n===hl, lab=n.replace("а","А");
    const e = mk(ll, `<div class="cmk ${on?"hl":""}">${lab}</div>`, Z()?`${lab}号楼`:`Корпус ${lab}`, on);
    if(on) e.style.zIndex=5;
  }
  for(const [n,ll] of Object.entries(D.gates)) mk(ll, `<div class="gmk">П${n}</div>`, Z()?`${n}号门（入口）`:`Проходная №${n}`);
  mk(D.ligovsky, `<div class="cmk ${hl==="32"?"hl":""}">32</div>`, Z()?"32号楼 · 利戈夫斯基大街275号":"Корпус 32 · Лиговский пр., 275", hl==="32");
}
