const CAMPUS_KNOWN = ["13","12","11","2","4","5","7","10","9","8","6","21","20","20а","15","14","16","19","1","3","17","18"];
// ================================================================ звонки и пропуски (экраны)
function statsScreen(ctx){
  const t=L(), g=myGroup(), ab=absents();
  const past = g.lessons.filter(l=>countable(l) && started(l,ctx)), by = new Map();
  for(const l of past){
    const k=l.subject.ru; if(!by.has(k)) by.set(k,{key:k, subject:l.subject, total:0, miss:0, list:[]});
    const e=by.get(k); e.total++; e.list.push(l); if(ab[noteKey(g.id,l)]) e.miss++;
  }
  let rows=[...by.values()].sort((a,b)=>b.miss-a.miss || a.subject.ru.localeCompare(b.subject.ru,"ru"));
  if(state.statOrder && state.statOrder.g===g.id) rows.sort((a,b)=>state.statOrder.list.indexOf(a.key)-state.statOrder.list.indexOf(b.key));
  else state.statOrder={g:g.id, list:rows.map(r=>r.key)};
  const tot=past.length, miss=rows.reduce((s,r)=>s+r.miss,0), pct=tot?Math.round((tot-miss)/tot*100):100;
  const bar = (p,c) => `<div class="pbar ${p<70?"bad":""}"><div style="width:${p}%;${c&&p>=70?`background:${c}`:""}"></div></div>`;
  let h = `<p class="muted small">${t.stHint}</p><div class="card summary">${bar(pct)}<div>✅ ${t.stVisited}: <b>${tot-miss} ${t.exOf} ${tot}</b> (${pct}%)</div><div>❌ ${t.stMissed}: <b>${miss}</b></div></div>`;
  const plan = g.lessons.filter(l=>countable(l) && !started(l,ctx) && ab[noteKey(g.id,l)]);
  if(plan.length) h += `<h3>${t.stPlan} · ${plan.length}</h3><p class="muted small">${t.stPlanHint}</p><div class="card stdates">${plan.map(l=>{ const f=fmtDay(l.date);
    return `<div><span><i class="sdot" style="background:${colorOf(l.subject.ru)}"></i> ${f.d}, ${t.wdS[parse(l.date).getUTCDay()]} · ${l.start} — ${esc(tr(l.subject))}</span><button class="btn small ghost" data-act="absentS" data-v="${enc(noteKey(g.id,l))}">${t.stUnplan}</button></div>`; }).join("")}</div>`;
  if(!rows.length) return h + emptyBox(t.stNone);
  return h + rows.map(r=>{
    const p=Math.round((r.total-r.miss)/r.total*100), open=state.statOpen===r.key;
    return `<div class="card stbox"><button class="sthead" data-act="statOpen" data-v="${enc(r.key)}"><i class="sdot" style="background:${colorOf(r.key)}"></i><b>${esc(tr(r.subject))}</b><span>${open?"▲":"▼"}</span></button>${bar(p, colorOf(r.key))}
      <div class="muted small">${t.stRow(r.total-r.miss, r.total, r.miss)} · ${p}%</div>
      ${open?`<div class="stdates">${r.list.slice().reverse().map(l=>{ const k=noteKey(g.id,l), off=!!ab[k], f=fmtDay(l.date);
        return `<div class="${off?"miss":""}"><span>${off?"❌":"✅"} ${f.d}, ${t.wdS[parse(l.date).getUTCDay()]} · ${l.start}</span><span class="muted small">${esc(tr(l.type))}</span>
          <button class="btn small ${off?"ghost":"danger"}" data-act="absentS" data-v="${enc(k)}">${off?t.stWas:t.stMiss}</button></div>`; }).join("")}</div>`:""}</div>`; }).join("");
}

