function lkKind(x){
  if(x.ic && LK_ART[x.ic]) return x.ic;
  const u=(x.u||"").toLowerCase(), t=(x.t||"").toLowerCase();
  if(u.startsWith("tel:")) return "phone";
  if(/\/\/(vk\.me|vk\.ru|vk\.com|m\.vk)/.test(u)) return "vk";
  if(/\/\/(www\.)?max\.ru/.test(u)) return "max";
  if(/\/\/t\.me\//.test(u)) return "tg";
  if(/wechat\.com|weixin/.test(u)) return "wx";
  if(/schedule|guide\.herzen/.test(u)) return "cal";
  if(/check-in|читательск/.test(u+t)) return "card";
  if(/lib\.herzen|ebs|учебник|библиот/.test(u+t)) return "books";
  if(/psy|психолог/.test(u+t)) return "heart";
  if(/grants|стипенд/.test(u+t)) return "coins";
  if(/dorm|общежит/.test(u+t)) return "home";
  if(/gosuslugi/.test(u)) return "gos";
  if(/culture\.ru|pushkin/.test(u)) return "ticket";
  if(/consultant|garant/.test(u)) return "law";
  if(/\.pdf($|\?)|7771000/.test(u) || /памятк|брошюр|документ/.test(t)) return "doc";
  if(/herzen|hspu/.test(u)) return "uni";
  return "web";
}
const lkIcon = x => { const a=LK_ART[lkKind(x)]; return `<i class="lkic" style="background:${a[0]}"><svg viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">${a[1]}</svg></i>`; };
function groupLinksHTML(){
  const t=L(), g=String(state.group), adm=devMode(), me=isAdmin() && pinOk(), a=acct();
  const all=(SHARED.links||[]).filter(x=>(x.g||[]).map(String).includes(g) && safeUrl(x.u));
  const vis=all.filter(x=>me || x.pub || (a && (!x.r || inRoster(g))));
  const hidden=all.length>vis.length && !a;
  if(!vis.length && !hidden && !adm) return "";
  const row=x=>`<a class="row" href="${esc(x.u.trim())}" ${x.u.startsWith("tel:")?"":`target="_blank" rel="noopener"`}>${lkIcon(x)}<span><b>${esc((Z()&&x.tz)||x.t||x.u)}</b><small>${esc((Z()&&x.sz)||x.s||x.u.replace(/^https:\/\//,"").replace(/^tel:/,"").slice(0,48))}</small></span>${icon("chev","sm muted")}</a>`;
  return `<h3>${t.glT}</h3><div class="list">${vis.map(row).join("")}
    ${hidden?`<button class="row" data-act="openAccount">${icon("groups")}<span><b>${t.glMore}</b><small>🔒 ${t.glLocked}</small></span>${icon("chev","sm muted")}</button>`:""}
    ${adm?`<button class="row" data-act="glEdit">${icon("edit")}<span><b>${t.glEdit}</b><small>${t.glEditSub}</small></span>${icon("chev","sm muted")}</button>`:""}</div>`;
}
