// ================================================================ нижние окна
// Окна складываются в стопку: «назад» (кнопка в окне или системная) возвращает на один шаг.
let SH=[], sheetEntry=0;   // sheetEntry — сколько шагов истории сейчас занимают открытые окна
let sheetFocus=null;
document.addEventListener("keydown", e=>{ if(e.key!=="Tab" || !$("modal") || !$("modal").classList.contains("open")) return;
  const f=[...$("sheet").querySelectorAll('button,a[href],input,select,textarea,[tabindex]:not([tabindex="-1"])')].filter(x=>!x.disabled && x.offsetParent!==null); if(!f.length) return;
  const a=f[0], z=f[f.length-1];
  if(!$("sheet").contains(document.activeElement)){ e.preventDefault(); a.focus(); }
  else if(e.shiftKey && document.activeElement===a){ e.preventDefault(); z.focus(); }
  else if(!e.shiftKey && document.activeElement===z){ e.preventDefault(); a.focus(); } });
document.addEventListener("keydown", e=>{ if(e.key==="Escape" && $("modal") && $("modal").classList.contains("open")){ e.preventDefault(); sheetBack(); } });
function openSheet(html){
  if(!$("modal").classList.contains("open")) sheetFocus=document.activeElement;
  setTimeout(ariaMarks, 0);
  { const tt=document.getElementById("toast"); if(tt) tt.className=""; }   // окно открылось — подсказку внизу убираем, чтобы не закрывала кнопки
  $("sheet").innerHTML = `<div class="grab"></div><button class="close" data-act="close" aria-label="${L().back}">${icon(SH.length>1?"back":"x")}</button>` + html;
  $("modal").classList.add("open"); $("modal").setAttribute("role","dialog"); $("modal").setAttribute("aria-modal","true");
  setTimeout(()=>{ const h=$("sheet").querySelector("h2"); if(h && !$("sheet").contains(document.activeElement)){ h.setAttribute("tabindex","-1"); h.focus({preventScroll:true}); } }, 30); document.documentElement.classList.add("lock");
}
function pushSheet(fn){
  SH.push(fn); fn(); $("sheet").scrollTop=0;
  history.pushState({...(history.state||{}), sheet:SH.length}, ""); sheetEntry++;   // шаг добавляем сразу по нажатию — тогда системная «назад» его не пропустит
}
function refreshSheet(){ if(!SH.length) return; const sh=$("sheet"), y=sh.scrollTop;
  const typed={}; sh.querySelectorAll("textarea[id], input[id]:not([type=checkbox]):not([type=radio]):not([type=file]):not([type=range])").forEach(e=>{ if(e.value!==e.defaultValue) typed[e.id]=e.value; });   // не терять набранный текст
  SH[SH.length-1](); Object.entries(typed).forEach(([id,v])=>{ const e=$(id); if(e) e.value=v; }); sh.scrollTop=y; }
function sheetBack(){ if(SH.length>1){ if(sheetEntry>1) history.back(); else { SH.pop(); refreshSheet(); $("sheet").scrollTop=0; } } else closeSheet(); }
let installAfterSheet=false;
let afterClose=null;
function closeSheet(after){ setTimeout(()=>{ if(sheetFocus && document.body.contains(sheetFocus)) try{ sheetFocus.focus({preventScroll:true}); }catch(e){} sheetFocus=null; }, 0);
  SH=[]; ($("modal").classList.remove("open"), document.documentElement.classList.remove("lock")); state.sheet=null;
  installAfterSheet=false;
  if(sheetEntry){ const n=sheetEntry; sheetEntry=0; if(typeof after==="function") afterClose=after; history.go(-n); }
  else if(typeof after==="function") after();
}
let reopenStack=null, reopenY=0, reopenDepth=1;   // окна, которые надо вернуть, когда человек нажмёт «назад»
function goFromSheet(screen, prevTeacher=state.teacher){   // перейти на экран прямо из окна; «назад» вернёт в это же окно
  if(!sheetEntry) return go(screen);
  reopenStack=SH.slice(); reopenY=scrollY; reopenDepth=sheetEntry;
  const prev=state.screen;
  SH=[]; ($("modal").classList.remove("open"), document.documentElement.classList.remove("lock")); sheetEntry=0;
  history.replaceState({screen:prev, teacher:prevTeacher, reopen:1, sheet:1}, "");
  if(screen!==prev) state.hwArch=false;
  state.screen=screen; history.pushState({screen, teacher:state.teacher}, ""); window.scrollTo({top:0}); render();
}
function reopenSheets(){
  const st=reopenStack; reopenStack=null; if(!st||!st.length) return;
  requestAnimationFrame(()=>{ scrollTo(0,reopenY); SH=st; SH[SH.length-1](); $("sheet").scrollTop=0;
    sheetEntry=Math.max(1, reopenDepth); });   // этот шаг истории — тот же, что был у окна (новый не добавляем)
}
