let nSel=null;
// Уведомления от сайта (OneSignal). SDK грузится только когда нужно.
let OS=null;
function loadOneSignal(){
  if(OS) return OS;
  OS = new Promise((ok,fail)=>{
    if(!DATA.push) return fail(new Error("no app id"));
    window.OneSignalDeferred = window.OneSignalDeferred || [];
    const sc=document.createElement("script"); sc.src="https://cdn.onesignal.com/sdks/web/v16/OneSignalSDK.page.js"; sc.defer=true; sc.onerror=()=>fail(new Error("cdn"));
    document.head.appendChild(sc);
    const path=location.pathname.replace(/[^/]*$/,"");
    window.OneSignalDeferred.push(async O=>{
      try{ await O.init({appId:DATA.push, safari_web_id:"web.onesignal.auto.61cc1b76-79db-483e-a0b9-263210abb193", serviceWorkerPath:path.slice(1)+"sw.js", serviceWorkerParam:{scope:path}, allowLocalhostAsSecureOrigin:true}); ok(O); }catch(e){ fail(e); }
    });
    setTimeout(()=>fail(new Error("timeout")), 15000);
  });
  OS.catch(()=>{ OS=null; });   // не получилось (VPN, плохая сеть) — следующая попытка начнётся заново
  return OS;
}
