async function sendReport(){
  const t=L(), txt=$("r_text").value.trim(), m=$("f_msg");
  if(!txt){ m.textContent=t.rEmpty; return; }
  const types={sched:"Расписание",tr:"Перевод",site:"Сайт",other:"Другое"};
  m.innerHTML=SPIN;
  try{
    const r = await fetch("https://ntfy.sh/", {method:"POST", body:JSON.stringify({topic:`${DATA.notify}-report`,
      title:`🐞 ${types[rType]} · ${myGroup().label} · ${state.lang}`, message:`${txt}\n\n— ${$("r_name").value.trim()||"аноним"}`, tags:["bug"]})});
    if(!r.ok) throw new Error(r.status);
    m.textContent=t.rOk; $("r_text").value="";
  }catch(e){ m.textContent=t.rErr; }
}

