// HSL ⇄ HEX
function hexToHsl(h){ let [r,g,b]=hexRgb(h).map(x=>x/255); const mx=Math.max(r,g,b), mn=Math.min(r,g,b); let hh=0,s=0; const l=(mx+mn)/2;
  if(mx!==mn){ const d=mx-mn; s=l>.5?d/(2-mx-mn):d/(mx+mn); hh = mx===r?(g-b)/d+(g<b?6:0) : mx===g?(b-r)/d+2 : (r-g)/d+4; hh*=60; }
  return [Math.round(hh), Math.round(s*100), Math.round(l*100)]; }
function hslToHex(h,s,l){ s/=100; l/=100; const k=n=>(n+h/30)%12, a=s*Math.min(l,1-l), f=n=>l-a*Math.max(-1,Math.min(k(n)-3,Math.min(9-k(n),1)));
  return "#"+[f(0),f(8),f(4)].map(x=>Math.round(x*255).toString(16).padStart(2,"0")).join(""); }
let pickSubj=null;
function pickTarget(){ return pickSubj==="@mono"?"mono":pickSubj==="@accent"?"accent":"subj"; }
function savePicked(c){
  const k=pickTarget();
  if(k==="mono"){ c ? LS.set("monoBase",c) : LS.del("monoBase"); }
  else if(k==="accent"){ LS.set("accent", c || "violet"); applyTheme(); }
  else { const o=LS.get("subjColors",{}); if(c) o[pickSubj]=c; else delete o[pickSubj]; LS.set("subjColors",o); }
}
function openPicker(ru){
  pickSubj=ru; const t=L(), mode=pickTarget();
  const cur = mode==="mono" ? LS.get("monoBase","#5b4bdb") : mode==="accent" ? accentBase() : colorOf(ru), [h,s,l]=hexToHsl(cur);
  const subj = mode==="mono" ? {ru:t.colMonoBase, zh:t.colMonoBase} : mode==="accent" ? {ru:t.colAccent, zh:t.colAccent} : (allSubjects().find(x=>x.ru===ru) || {ru, zh:ru});
  const quick = [...new Set([...paletteColors(), ...PALETTES.apple.c, ...Object.values(ACCENTS)])];
  openSheet(`<h2>${mode==="subj"?t.pickTitle:esc(tr(subj))}</h2>${mode==="subj"?`<p class="muted">${esc(tr(subj))}</p>`:""}
    <h3>${t.pickQuick}</h3><div class="quick">${quick.map(c=>`<button data-act="quickColor" data-v="${c}" style="background:${c}" class="${c===cur?"on":""}"></button>`).join("")}</div>
    <h3>${t.pickOwn}</h3>
    <label class="sl">${t.pickHue}<input type="range" id="ph" min="0" max="359" value="${h}" class="hue"></label>
    <label class="sl">${t.pickSat}<input type="range" id="ps" min="0" max="100" value="${s}"></label>
    <label class="sl">${t.pickLight}<input type="range" id="pl" min="10" max="90" value="${l}"></label>
    <h3>${t.pickPreview}</h3><div id="pprev"></div>
    <div class="btnrow"><button class="btn" data-act="saveColor">${t.pickSave}</button><button class="btn ghost" data-act="resetColor">${mode==="subj"?t.pickReset:t.pickDefault}</button></div>`);
  updatePicker();
}
function updatePicker(){
  const h=+$("ph").value, s=+$("ps").value, l=+$("pl").value, c=hslToHex(h,s,l);
  $("ps").style.background = `linear-gradient(90deg, ${hslToHex(h,0,l)}, ${hslToHex(h,100,l)})`;
  $("pl").style.background = `linear-gradient(90deg, #000, ${hslToHex(h,s,50)}, #fff)`;
  const t0=L(), subj = pickTarget()==="mono" ? {ru:t0.colMonoBase, zh:t0.colMonoBase} : (allSubjects().find(x=>x.ru===pickSubj) || {ru:pickSubj, zh:pickSubj});
  if(pickTarget()==="accent"){
    const bg=isDark()?"#1c1a27":"#ffffff", fixed=readable(c,bg,3), ink=contrast(fixed,"#fff")>=contrast(fixed,"#111")?"#fff":"#111";
    $("pprev").innerHTML = `<div class="accprev" style="--accent:${fixed};--accent-soft:${rgba(fixed,.14)};--accent-ink:${ink}"><span class="btn small">${L().colAccentBtn}</span><span class="accday">23</span><span class="acctab">${icon("today","sm")} ${L().today}</span><span class="acclink">${L().colAccentLink}</span></div>
      ${fixed!==c?`<p class="muted small">⚠️ ${L().colAccentFixed}</p>`:""}${warmWarning(c)?`<p class="muted small">⚠️ ${L().colAccentWarm}</p>`:""}`;
  } else {
    $("pprev").innerHTML = `<div class="lesson" style="--c:${c};--tint:${rgba(c,isDark()?.2:.13)}"><div class="time"><b>11:20</b><span>12:50</span></div><div class="info"><div class="subj">${esc(tr(subj))}</div><div class="meta">${icon("pin","sm")}<span>${Z()?"32号楼 213教室":"корп. 32, ауд. 213"}</span></div></div></div>`;
  }
  $("pprev").dataset.c = c;
}
