// перетаскивание: тянем за ⠿ (или держим строку полсекунды)
let drag=null;
function navDragStart(row, y){
  const list=row.parentElement; if(!list || !(/^(navlist|tilelist)$/.test(list.id) || list.dataset.dord)) return;
  drag={row, list, y0:y, rows:[...list.querySelectorAll(".navrow")]};
  row.classList.add("dragging"); if(navigator.vibrate) navigator.vibrate(15);
}
// мышью — сразу за любую часть строки; пальцем — сразу за ⠿, за остальную строку только после удержания 0,4 с,
// иначе обычный свайп листает список (раньше любое касание двигало строку и до конца списка было не долистать)
let navHold=null;
const navHoldOff=()=>{ if(navHold){ clearTimeout(navHold.t); navHold=null; } };
document.addEventListener("pointerdown", e=>{
  const row=e.target.closest(".navrow"); if(!row || e.target.closest(".mv")) return;
  if(e.pointerType==="mouse" || e.target.closest(".grip")){ e.preventDefault(); navDragStart(row, e.clientY); return; }
  navHoldOff(); const y=e.clientY; navHold={y, t:setTimeout(()=>{ navHold=null; navDragStart(row, y); }, 400)};
});
document.addEventListener("touchmove", e=>{ if(drag) e.preventDefault(); }, {passive:false});   // строку тащим — страница не листается
document.addEventListener("pointermove", e=>{
  if(navHold && Math.abs(e.clientY-navHold.y)>8) navHoldOff();
  if(!drag) return; e.preventDefault();
  const dy=e.clientY-drag.y0; drag.row.style.transform=`translateY(${dy}px)`;
  const others=drag.rows.filter(r=>r!==drag.row);
  for(const r of others){ const b=r.getBoundingClientRect(), mid=b.top+b.height/2;
    if(dy<0 && e.clientY<mid && r.compareDocumentPosition(drag.row)&Node.DOCUMENT_POSITION_FOLLOWING){ drag.list.insertBefore(drag.row, r); drag.y0=e.clientY; drag.row.style.transform=""; break; }
    if(dy>0 && e.clientY>mid && r.compareDocumentPosition(drag.row)&Node.DOCUMENT_POSITION_PRECEDING){ drag.list.insertBefore(drag.row, r.nextSibling); drag.y0=e.clientY; drag.row.style.transform=""; break; } }
}, {passive:false});
const navDrop = ()=>{
  if(!drag) return; drag.row.classList.remove("dragging"); drag.row.style.transform="";
  const order=[...drag.list.querySelectorAll(".navrow")].map(r=>r.dataset.k), isTiles=drag.list.id==="tilelist", dk=drag.list.dataset.dord; drag=null;
  if(dk){ DORD.drop(dk, order); return; }
  if(isTiles){ const all=tileOrder(), next=[...order, ...all.filter(x=>!order.includes(x))]; if(JSON.stringify(next)!==JSON.stringify(all)){ LS.set("tileOrder", next); render(); } return; }
  if(JSON.stringify(order)!==JSON.stringify(navItems())){ LS.set("nav", order); render(); }
};
document.addEventListener("pointerup", ()=>{ navHoldOff(); navDrop(); }); document.addEventListener("pointercancel", ()=>{ navHoldOff(); navDrop(); });   // системный жест тоже отпускает строку
/* Порядок и скрытые папки/термины Словаря — общие для Словаря (gym.js) и Карточек (cards.js).
   dictOrd: {ключ родителя: [id детей по порядку]} — ключи "root" (темы), "t:<тема>" (главы), "c:<глава>" (подразделы).
   dictHid: ["t:<тема>", "c:<глава>", "k:<подраздел>", "i:<термин>"]. Новые главы/подразделы, которых нет в сохранённом порядке,
   встают после того соседа, за которым идут в учебнике. Оба ключа синхронизируются с аккаунтом. */
const DORD = (() => {
  const TX = {ru:{h:"Порядок и скрытые", hint:"Перетащите за ⠿, чтобы поменять местами. Глаз — спрятать то, что не нужно. Порядок общий для Словаря и Карточек.", reset:"Как в учебнике", hidden:"скрыто", hideT:"Скрыть", showT:"Показать"},
              zh:{h:"排序和隐藏", hint:"拖动 ⠿ 调整顺序。点眼睛可以隐藏不需要的内容。词典和卡片使用同一个顺序。", reset:"恢复教材顺序", hidden:"已隐藏", hideT:"隐藏", showT:"显示"}};
  const tt = () => TX[state.lang==="zh"?"zh":"ru"];
  let hs = null, hraw; const LIS = [];   // hraw — undefined, пока не читали (getItem без ключа даёт null)
  const ord = () => LS.get("dictOrd", {});
  const hidSet = () => { const r = localStorage.getItem("dictHid"); if(r!==hraw){ hraw = r; hs = new Set(LS.get("dictHid", [])); } return hs; };
  const changed = () => { LIS.forEach(f => { try{ f(); }catch(e){ console.error(e); } }); render(); refreshSheet(); };
  function sort(key, ids){   // ids — порядок учебника
    const o = (ord()[key] || []).filter(x => ids.includes(x)); if(!o.length) return ids.slice();
    const out = o.slice();
    ids.forEach((x, i) => { if(out.includes(x)) return; let j = i-1; while(j>=0 && !out.includes(ids[j])) j--; out.splice(j<0 ? 0 : out.indexOf(ids[j])+1, 0, x); });
    return out;
  }
  const hid = k => hidSet().has(k);
  function toggle(k){ const h = [...hidSet()]; LS.set("dictHid", h.includes(k) ? h.filter(x => x!==k) : [...h, k]); changed(); }
  let cur = null;   // открытое окно: {key, title, kind, rows:[{id, name}]}
  function open(key, title, kind, rows){ cur = {key, title, kind, rows};
    pushSheet(() => { const t = tt(), c = cur, ids = sort(c.key, c.rows.map(r => r.id)), nm = Object.fromEntries(c.rows.map(r => [r.id, r.name]));
      openSheet(`<h2>${t.h}</h2><p class="muted small">${esc(c.title)} · ${t.hint}</p><div class="list" data-dord="${esc(c.key)}">${ids.map(id => { const h = hid(c.kind+":"+id);
        return `<div class="row navrow ${h?"hid":""}" data-k="${esc(id)}"><span class="grip" aria-label="⠿">${icon("drag")}</span><span><b>${nm[id]}</b>${h?`<small>${t.hidden}</small>`:""}</span>`
          + `<button class="mv" data-act="dordHide" data-v="${esc(c.kind+":"+id)}" aria-label="${h?t.showT:t.hideT}">${icon(h?"eyeoff":"eye","sm")}</button></div>`; }).join("")}</div>`
        + `<button class="btn wide ghost" data-act="dordReset">${t.reset}</button>`); });
  }
  function drop(key, order){ const o = ord(); if(JSON.stringify(o[key]||[])===JSON.stringify(order)) return; o[key] = order; LS.set("dictOrd", o); changed(); }
  function reset(){ if(!cur) return; const o = ord(); delete o[cur.key]; LS.set("dictOrd", o);
    const ks = new Set(cur.rows.map(r => cur.kind+":"+r.id)); LS.set("dictHid", [...hidSet()].filter(x => !ks.has(x))); changed(); }
  return {sort, hid, toggle, open, drop, reset, on:f => LIS.push(f), tt};
})();
