let toastTimer=null;
function toast(text, btn, fn){
  let el=$("toast"); if(!el){ el=document.createElement("div"); el.id="toast"; el.setAttribute("role","status"); el.setAttribute("aria-live","polite"); document.body.appendChild(el); }
  el.innerHTML=`<span>${esc(text)}</span>${btn?`<button id="toastbtn">${esc(btn)}</button>`:""}`; el.className="show";
  if(btn) $("toastbtn").onclick=()=>{ el.className=""; fn&&fn(); };
  clearTimeout(toastTimer); toastTimer=setTimeout(()=>el.className="", 6000);
}

