const dataDump = () => JSON.stringify({app:"raspisanie", v:1, at:new Date().toISOString(), data:Object.fromEntries(MY_KEYS.map(k=>[k, localStorage.getItem(k)]).filter(([,v])=>v!==null))});
function dataRestore(txt){
  const t=L(), m=$("f_msg");
  try{ const d=JSON.parse(txt); if(d.app!=="raspisanie") throw 0;
    Object.entries(d.data).forEach(([k,v])=>{ if(MY_KEYS.includes(k) && typeof v==="string"){ let ok=true; try{ const p=JSON.parse(v); ok = LS_ARR.includes(k)?Array.isArray(p) : LS_OBJ.includes(k)?(p&&typeof p==="object"&&!Array.isArray(p)) : k==="avatar"?!!safeAvatar(p) : true; }catch(e){ ok=false; }
      if(ok){ localStorage.setItem(k,v); if(SYNC_KEYS.includes(k)) touchSync(k); } } });
    m.textContent=t.dDone; setTimeout(()=>location.reload(), 900);
  }catch(e){ m.textContent=t.dBad; }
}

