document.addEventListener("click", e=>{
  const el = e.target.closest("[data-act]");
  if(!el){ if(e.target.id==="modal") closeSheet(); return; }
  { const a=e.target.closest("a[href]"); if(a && a!==el && el.contains(a)) return; }   // ссылка внутри нажимаемой карточки — пусть откроется как ссылка
  const fn = ACT[el.dataset.act]; if(!fn) return;
  if(el.tagName==="A" && el.getAttribute("href")) return;
  if(el.type!=="checkbox") e.preventDefault();
  const res=fn(el.dataset.v, el);
  if(res && typeof res.then==="function" && el.tagName==="BUTTON" && !el.classList.contains("busy")){   // долгое действие — кнопка с крутилкой, повторно не нажать
    el.classList.add("busy"); el.disabled=true; res.finally(()=>{ el.classList.remove("busy"); el.disabled=false; }); }
});
// ---- фото профиля: выбор → окно кадрирования (двигать, масштаб, поворот) → круг 256×256
let crop=null;   // {img, rot, z, x, y} — x,y: смещение центра фото относительно центра круга (в px окна), z: множитель к «заполнить круг»
async function setAvatar(file){
  try{ const bmp=await createImageBitmap(file), k=Math.min(1,1400/Math.max(bmp.width,bmp.height)), c=document.createElement("canvas");
    c.width=Math.round(bmp.width*k); c.height=Math.round(bmp.height*k); c.getContext("2d").drawImage(bmp,0,0,c.width,c.height);
    const blob=await new Promise(ok=>c.toBlob(ok,"image/jpeg",.85)); await fPut("avatarSrc", blob);   // оригинал — чтобы потом перенастроить
    openCrop(blob, {rot:0,z:1,x:0,y:0});
  }catch(e){ toast(L().phErr); }
}
async function openCrop(blob, st){
  const img=await createImageBitmap(blob); crop={img, ...st};
  const t=L();
  pushSheet(()=>{ openSheet(`<h2>${t.crTitle}</h2><p class="muted small">${t.crHint}</p>
    <div class="crop" id="crop"><canvas id="crc" width="600" height="600"></canvas><div class="cring"></div></div>
    <label class="crz">${t.crZoom}<input type="range" id="crz" min="1" max="5" step="0.01" value="${crop.z}"></label>
    <div class="btnrow" style="justify-content:center"><button class="btn small ghost" data-act="crRot">↻ ${t.crRot}</button></div>
    <div class="btnrow"><button class="btn" data-act="crSave">${t.save}</button><button class="btn ghost" data-act="crCancel">${t.cancel2}</button></div>`);
    cropDraw(); cropBind(); });
}
function cropGeom(W){   // размеры фото на холсте W×W при текущем масштабе
  const r=crop.rot%180!==0, iw=r?crop.img.height:crop.img.width, ih=r?crop.img.width:crop.img.height, base=W/Math.min(iw,ih);
  return {iw, ih, sc:base*crop.z};
}
function cropClamp(W){   // фото не должно открывать пустоту внутри круга
  const g=cropGeom(W), mx=Math.max(0,(g.iw*g.sc-W)/2), my=Math.max(0,(g.ih*g.sc-W)/2);
  crop.x=Math.max(-mx,Math.min(mx,crop.x)); crop.y=Math.max(-my,Math.min(my,crop.y));
}
function cropPaint(ctx, W, k=1){
  const g=cropGeom(W); ctx.save(); ctx.fillStyle="#fff"; ctx.fillRect(0,0,W,W);
  ctx.translate(W/2+crop.x*k, W/2+crop.y*k); ctx.rotate(crop.rot*Math.PI/180);
  const w=crop.img.width*g.sc, h=crop.img.height*g.sc; ctx.drawImage(crop.img,-w/2,-h/2,w,h); ctx.restore();
}
function cropDraw(){ const c=$("crc"); if(!c||!crop) return; cropClamp(c.width); cropPaint(c.getContext("2d"), c.width); }
function cropBind(){
  const box=$("crop"), c=$("crc"), pts=new Map(); let last=null;
  const ratio=()=>c.width/box.clientWidth;
  box.addEventListener("pointerdown", e=>{ box.setPointerCapture(e.pointerId); pts.set(e.pointerId,{x:e.clientX,y:e.clientY}); last=null; });
  box.addEventListener("pointermove", e=>{ if(!pts.has(e.pointerId)) return; const prev=pts.get(e.pointerId); pts.set(e.pointerId,{x:e.clientX,y:e.clientY});
    if(pts.size===1){ crop.x+=(e.clientX-prev.x)*ratio(); crop.y+=(e.clientY-prev.y)*ratio(); }
    else if(pts.size===2){ const [a,b]=[...pts.values()], d=Math.hypot(a.x-b.x,a.y-b.y); if(last) { crop.z=Math.max(1,Math.min(5,crop.z*d/last)); $("crz").value=crop.z; } last=d; }
    cropDraw(); });
  const up=e=>{ pts.delete(e.pointerId); last=null; }; box.addEventListener("pointerup",up); box.addEventListener("pointercancel",up);
  box.addEventListener("wheel", e=>{ e.preventDefault(); crop.z=Math.max(1,Math.min(5,crop.z*(e.deltaY<0?1.08:1/1.08))); $("crz").value=crop.z; cropDraw(); }, {passive:false});
  $("crz").addEventListener("input", e=>{ crop.z=+e.target.value; cropDraw(); });
}
function cropSave(){
  const W=600, c=document.createElement("canvas"); c.width=c.height=256; cropClamp(W);
  const ctx=c.getContext("2d"); ctx.scale(256/W,256/W); cropPaint(ctx, W);
  LS.set("avatar", c.toDataURL("image/jpeg",.85)); LS.set("avatarCrop", {rot:crop.rot,z:crop.z,x:crop.x,y:crop.y}); crop=null;
  render(); sheetBack();
}
