function alphaJump(e){
  const p=e.touches?e.touches[0]:e, el=document.elementFromPoint(p.clientX,p.clientY);
  const l=el && el.dataset && el.dataset.l; if(!l) return;
  const target=$("al-"+l); if(target){ window.scrollTo({top:target.getBoundingClientRect().top+window.scrollY-70}); }
  document.querySelectorAll("#alpha span").forEach(s=>s.classList.toggle("on", s.dataset.l===l));
}
document.addEventListener("touchstart", e=>{ if(e.target.closest("#alpha")){ alphaJump(e); } }, {passive:true});
