const APP_V = ((document.querySelector('script[src*="app.js?v="]')||{}).src||"").replace(/.*v=/,"");
let updChecked=0;
async function checkUpdate(){
  if(!APP_V || Date.now()-updChecked<60e3 || !navigator.onLine || document.getElementById("gate")) return; updChecked=Date.now();
  try{ const html=await (await fetch("./?u="+Date.now(), {cache:"no-store"})).text(), m=html.match(/app\.js\?v=(\d+)/);
    if(!m || m[1]===APP_V) return;
    const tried=JSON.parse(sessionStorage.getItem("updTry")||"{}");   // защита от бесконечных перезагрузок
    if(tried.v===m[1] && Date.now()-tried.t<10*60e3) return;
    sessionStorage.setItem("updTry", JSON.stringify({v:m[1], t:Date.now()}));
    const busy = document.querySelector("#modal.open") || (document.activeElement && /INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName));
    if(!busy && document.visibilityState==="visible") return location.reload();
    toast(L().updReady, L().updBtn, ()=>location.reload()); clearTimeout(toastTimer);
  }catch(e){}
}
