const getJSON = (u, d) => sfetch(u+"?v="+Date.now()).then(r=>r.ok?r.json():d).catch(()=>d);
addEventListener("online", ()=>DATA&&render()); addEventListener("offline", ()=>DATA&&render());
getJSON("status.json", {ok:true}).then(st=>{ STATUS=st||{ok:true}; if(DATA) render(); });
gate().then(()=>Promise.all([getJSON("data.json", null), getJSON("overrides.json", {items:[]}), getJSON("changes.json", []), getJSON("shared.json", {locked:[], items:[]})]).then(([d,o,ch,sh])=>{
  if(!d) throw new Error("no data");
  window.__appStarted=true;
  const onEnter = () => { ghostOn=true; applyTheme(); enterFx(); };
  onEnter(); document.addEventListener("visibilitychange", ()=>{ if(document.visibilityState==="visible"){ onEnter(); render(); } });
  DATA=d; OVR=(o&&o.items)||[]; CHANGES=ch||[]; SHARED={locked:(sh&&sh.locked)||[], items:(sh&&sh.items)||[], sizes:(sh&&sh.sizes)||{}, adminKey:(sh&&sh.adminKey)||null, links:(sh&&sh.links)||[], roster:(sh&&sh.roster)||{}, me:(sh&&sh.me)||{}};
  if(!state.group || !DATA.groups.some(g=>g.id==state.group)) state.group=DATA.groups[0].id;
  if(!Array.isArray(state.cmp)) state.cmp=DATA.groups.map(g=>g.id);
  if(qs.get("g") && LS.get("group")!==state.group) LS.set("group",state.group);
  if(qs.get("lang") && LS.get("lang")!==state.lang) LS.set("lang",state.lang);
  if(qs.has("g")||qs.has("lang")){ const u=new URL(location.href); ["g","lang"].forEach(k=>u.searchParams.delete(k)); history.replaceState(history.state, "", u.pathname+(u.search||"")+u.hash); }   // применили один раз — дальше решает выбор пользователя
  render();
  if(LS.get("welcomed",false) && !sessionStorage.getItem("statDone")){ sessionStorage.setItem("statDone","1");
    const g=myGroup(); stat("/"+state.screen); stat("group-"+(g?g.label:"?"), "", true); stat("lang-"+state.lang, "", true);
    stat((isStandalone()?"app-":"browser-")+platform(), "", true); if(acct()) stat("account", "", true); }
  dailyPing();
  if(state.restoreY){ const y=state.restoreY; state.restoreY=0; requestAnimationFrame(()=>scrollTo(0,y)); setTimeout(()=>scrollTo(0,y), 300); }
  if(!LS.get("welcomed",false)) openWelcome();

  applyTrash();   // убрать старше 30 дней
  importShared();
  if(sessionStorage.getItem("mychIn") && LS.get("welcomed",false)) go("dict");   // ссылка на главу одногруппника — сразу в Словарь (там mych.js покажет главу)
  if(LS.get("tcShare",null)) loadTcs();   // контакты преподавателей от старосты: подгружаем сразу, чтобы после ссылки сразу сказать «готово»
  syncNow(); document.addEventListener("visibilitychange", ()=>{ if(document.visibilityState==="visible") syncNow(); }); addEventListener("online", syncNow); addEventListener("focus", syncNow);
  setInterval(()=>{ if(document.visibilityState==="visible") syncNow(); }, 5*60e3);   // реже — бережём бесплатный лимит Supabase; при правках и при возврате в приложение синхронизация и так сразу   // на компьютере вкладка может быть открыта весь день
  setInterval(()=>{ const a=document.activeElement; if(!$("modal").classList.contains("open") && state.screen!=="map" && !(a && /INPUT|TEXTAREA|SELECT/.test(a.tagName)) && !coachOn()) render(); }, 30000);
})).catch(e=>{ console.error(e); $("main").innerHTML=emptyBox(L().err); });
